In this work, we propose and investigate a novel normal map-based proximal stochastic gradient method for the composite problem
%
\begin{equation}
	\label{eq:SO} \min_{x\in \Rn}~\psi(x) := f(x) + \vp(x),
\end{equation}
%
where $\vp: \Rn \to \Rex$ is a convex, lower semicontinuous (lsc.), and proper mapping and $f: \Rn \to \R$ is continuously differentiable on an open set containing the effective domain $\dom{\vp} := \{x \in \Rn: \vp(x) < \infty\}$. 


where the sequence $\revise{\{\alpha_k\}_{k\in\N}}\subseteq \R_{++}$ denotes the selected step sizes, $g^k$ is a (stochastic) approximation of $\nabla f(x^k)$, and the well-known proximity operator of $\vp$ is defined as $\prox{\alpha \vp}(x) := {\argmin}_{y\in\Rn} \, \vp(y) + \frac{1}{2\alpha}\|x-y\|^2$, $\alpha >0$. \vspace{1mm}   


    \begin{enumerate}[label=\textup{\textrm{(H.\arabic*)}},leftmargin=3em,topsep=0ex,itemsep=1ex,partopsep=0ex]
        \item \label{A1} The gradient $\nabla f : \Rn \to \Rn$ is Lipschitz continuous on $\dom{\vp}$ with modulus $\sL>0$ and $\vp$ is convex, lsc., and proper.
        \item \label{A2} The objective function $\psi$ is bounded from below, i.e., $\bar \psi := \inf_{x \in \Rn}\,\psi(x) > -\infty$. 
    \end{enumerate}


In addition, we assume that there is a filtered probability space $(\Omega,\mathcal F,\revise{\{\mathcal F_k\}_{k\in\N}},\Prob)$ that can describe the stochastic components of the update \cref{eq:update-PSGD} and of other stochastic algorithms studied in this work in a unified way. In particular, each approximation $g^k$ is understood as a realization of an $\mathcal F_{k+1}$-measurable random vector $\sg^k : \Omega \to \Rn$. Thus, the stochastic process $\revise{\{\sx^k\}_{k\in\N}}$, associated with \cref{eq:update-PSGD} (or other stochastic methods), is adapted to the filtration $\revise{\{\mathcal F_k\}_{k\in\N}}$. We further define the stochastic error terms $\se^k : \Omega \to \Rn$ via $\se^k := \sg^k - \nabla f(\sx^k)$ and set $\Exp_k[\cdot] := \Exp[\cdot | \cF_k]$. We mainly work with the following conditions on the errors $\revise{\{\se^k\}_{k\in\N}}$ and step sizes $\revise{\{\alpha_k\}_{k\in\N}}$:
%
\vspace{1.5mm}
%
\begin{enumerate}[label=\textup{\textrm{(S.\arabic*)}},leftmargin=3em,topsep=0ex,itemsep=1ex,partopsep=0ex]
        \item \label{B1} The stochastic error $\se^k$ has mean zero, i.e., $\Exp_k[\se^k]=0$ almost surely (a.s.).
        \item \label{B2} There exists $\revise{\{\sigma_k\}_{k\in\N}}\subseteq \R_+$ such that $\Exp_k[\|\se^k\|^2]\leq \sigma_k^2$ a.s. for all $k$. 
        \item \label{B3} The step sizes $\revise{\{\alpha_k\}_{k\in\N}}$ satisfy $\alpha_k\to0$, $\sum_{k=0}^\infty \alpha_k = \infty$, and $\sum_{k=0}^{\infty}\alpha_k^2\sigma_k^2<\infty$.
    \end{enumerate}


Let $\lambda>0$, $\revise{\{\alpha_k\}_{k\in\N}}\subseteq \R_{++}$ be given. Choose $z^0\in\Rn$ and set $x^0=\proxl(z^0)$. \\[1mm]


\be\label{eq:update-short}
    \sz^{k+1} = \sz^k - \alpha_k(\sg^k + \lambda^{-1}(\sz^k-\sx^k)) \quad \text{and} \quad \sx^{k+1} = \proxl(\sz^{k+1}),
\ee

where $\sg^k$ is a (unbiased) stochastic approximation of $\nabla f(\sx^k)$.


We now briefly discuss common stationarity measures for proximal gradient-type methods and for the problem \cref{eq:SO}. The first-order optimality conditions associated with \cref{eq:SO} are given by $0 \in \partial \psi(x) = \nabla f(x) + \partial \vp(x)$. Here, $\partial \psi$ denotes the limiting subdifferential of $\psi$ and $\partial \vp$ is the standard subdifferential for convex functions, cf. \cite{rocwet98,baucom11}. A point $\bar x \in \dom{\vp}$ is called a stationary point of \cref{eq:SO} if $0 \in \partial \psi(\bar x)$ and we use $\crit(\psi)$ to denote the set of all stationary points of $\psi$. We further introduce the notation $\|\partial \psi(x)\|_{-} := \dist(0,\partial\psi(x)) := {\min}_{v\in\partial \psi(x)} \;\|v\|$. A point $\bar x \in \dom{\vp}$ is an $\varepsilon$-stationary point of $\psi$, $\varepsilon \geq 0$, if we have $\|\partial\psi(\bar x)\|_- \leq \varepsilon$. %\\[-2.5ex]


\[ x \in \crit(\psi) \quad \iff \quad \Fnat(x) := \lambda^{-1}(x-\proxl(x-\lambda \nabla f(x))) = 0, \quad \lambda > 0. \]

\begin{equation} \label{eq:norm-subdiff} \Fnor(z) = \nabla f(\proxl(z)) + \lambda^{-1}(z-\proxl(z)) \in \partial\psi(\proxl(z)) \quad \forall~z\in\Rn. \end{equation}

\begin{equation} \label{eq:stat-am} \|\Fnat(x)\| \leq \|\partial\psi(x)\|_- \quad \text{and} \quad \|\partial\psi(\prox{\lambda\vp}(z))\|_- \leq \|\Fnor(z)\| \end{equation}

We first present several basic estimates and properties that facilitate the analysis of $\NSGD$. Since $\vp$ is assumed to be convex, lsc., and proper (cf$.$ \ref{A1}), the proximity operator $\proxl$ is firmly nonexpansive, \cite{mor65,baucom11}. Hence, recalling $\sx^k = \proxl(\sz^k)$, it holds that
%
\begin{equation}\label{prox-prop}
    \|\sx^n-\sx^m\|^2 \leq \iprod{\sz^n-\sz^m}{\sx^n-\sx^m}\leq \norm{\sz^n-\sz^m}^2 \quad \forall~\revise{m<n} \quad \text{(a$.$s$.$)}.
\end{equation}

\begin{align}
    \nonumber \sz^n&=\sz^{n-1} -\alpha_{n-1}[\sg^{n-1}+ \tfrac{1}{\lambda}(\sz^{n-1} - \sx^{n-1})] =\sz^{n-1} - \alpha_{n-1}[\Fnor(\sz^{n-1}) +\se^{n-1}]	\\
     \nonumber &=\sz^m - {\sum}_{i=m}^{n-1}\alpha_i\Fnor(\sz^i) - {\sum}_{i=m}^{n-1} \alpha_i\se^i \\
    \nonumber &=\sz^m - {{\sum}_{i=m}^{n-1}\alpha_i}\Fnor(\sz^m) - {\sum}_{i=m}^{n-1} \alpha_i[\Fnor(\sz^i)-\Fnor(\sz^m)] - {\sum}_{i=m}^{n-1} \alpha_i\se^i \\ & = \sz^m - \tau_{m,n} \Fnor(\sz^m) + \scp^{m,n} \revise{\quad \forall~m<n,}\label{eq:pretty-important}
\end{align}

where $\tau_{m,n}:= {\sum}_{i=m}^{n-1}\alpha_i$ and $\scp^{m,n}:=-{\sum}_{i=m}^{n-1} \alpha_i[\Fnor(\sz^i)-\Fnor(\sz^m)] - {\sum}_{i=m}^{n-1} \alpha_i\se^i$.


\[
\scs_{m,n} :=\max_{m<j\leq n}\Big\|{\sum}_{i=m}^{j-1} \alpha_i \se^i\Big\|.
\]

\begin{align}
         \su^{m,n}  & :=  \lambda^{-1}(\sz^n-\sz^m) + \Fnor(\sz^m) \label{eq:u-def1}\\  &\;=  (\lambda^{-1}-\tau_{m,n}^{-1})(\sz^n-\sz^m) + \tau_{m,n}^{-1} \scp^{m,n} \label{eq:u-def2}\\
          &\;=  (1-\lambda^{-1}\tau_{m,n}) \Fnor(\sz^m) + \lambda^{-1}\scp^{m,n}, \quad \revise{m < n}.\label{eq:u-def3}
     \end{align}

\begin{definition}[Merit function]\label{def:mer-fun} Given $\lambda > 0$, we define the merit function: 
 \[\mer(z):=\psi(\prox{\lambda\vp}(z)) + \frac{\xi\lambda}{2}\|\Fnor(z)\|^2,\quad \text{where} \quad \xi:={(2+2\lambda^2 \sL^2)^{-1}}.\]
\end{definition}

\begin{definition}[Time indices]\label{def:time win}
Let $\sT>0$ and $\delta\in(0,1)$ be given. We introduce the mapping $\varpi:\N \to \N\cup \{\pm\infty\}$, $\varpi(k):=\sup\{n > k: \tau_{k,n} \leq \sT\}$, where $\tau_{m,n} = {\sum}_{k=m}^{n-1} \alpha_k$. The \emph{time indices} $\revise{\{t_k\}_{k\in\N}}$, associated with the \emph{time window} $\sT$ \revise{(and the step sizes $\{\alpha_k\}_{k \in \N}$)}, are defined as 
\[
t_0 := \inf\{i: \alpha_j \leq (1-\delta)\sT \text{ for all $j\geq i$}\}\quad \text{and} \quad t_{k+1} := \varpi(t_k).
\]
\end{definition}

\begin{equation}\label{index-def}
\fk(i) = \max\{k: t_k < i\}\quad \text{for all $i>t_0$}.
\end{equation}

It is evident that we have $t_{\fk(i)}<i\leq t_{\fk(i)+1}$ for all $i>t_0$.


\begin{equation}
    \label{eq:def delta and T}
    \sr_k := \scs_{t_{k},t_{k+1}}, \;\; \delta := \frac45, \;\;  \sT := \frac{\sqrt{\xi}}{8\Llambda},\quad \text{where} \quad \Llambda =\sL+\frac{2}{\lambda}, \;\; \xi =\frac{1}{2+2\lambda^2 \sL^2}.
\end{equation}

\begin{enumerate}[label=\textup{\textrm{(H.3)}},leftmargin=3em,topsep=2mm,itemsep=1ex,partopsep=0ex]
        \item \label{A3} The objective function $\psi : \Rn \to \Rex$ is definable. %\vspace{2mm}
\end{enumerate}


\[ \cX := \{\omega\in\Omega: {\liminf}_{k\to\infty}\; \|\sx^k(\omega)\| < \infty\}. %\vspace{-.25ex} 
\]

Clearly, if $\omega\in\cX$, then the realization $\revise{\{x^k\}_{k\in\N}} = \revise{\{\sx^k(\omega)\}_{k\in\N}}$ has at least one bounded subsequence and accumulation point. We will work with the following assumption: 
%\vspace{1.5mm}
 \begin{enumerate}[label=\textup{\textrm{(S.4)}},leftmargin=3em,topsep=1.5mm,itemsep=1ex,partopsep=0ex]
        \item \label{B4} The event $\cX \in \mathcal F$ occurs with probability $1$, i.e., $\Prob(\cX)=1$.
    \end{enumerate}

