\begin{lemma}
    \label{lem:err_estimate}
    Let \ref{B1}--\ref{B2} hold and let $\revise{\{\alpha_k\}_{k\in\N}}$ be given. Then for any (arbitrary) subsequence $\revise{\{t_k\}_{k\in\N}} \subseteq \N$, we have $\Exp[{{\scs_{t_k,t_{k+1}}^2}}] \leq 4 \sum_{i=t_k}^{t_{k+1}-1}\alpha_i^2\sigma_i^2$. Moreover, if there is a non-decreasing sequence $\revise{\{\beta_k\}_{k\in\N}}\subset\R_{++}$ such that ${\sum}_{k=0}^\infty \alpha_k^2\beta_k^2\sigma_k^2 < \infty$, it holds that
    %
    \[ {\sum}_{k=0}^\infty \beta_{t_k}^2 \Exp[{{\scs_{t_k,t_{k+1}}^2}}] < \infty \quad \text{and}\quad {\sum}_{k=0}^\infty \beta_{t_k}^2 \scs_{t_k,t_{k+1}}^2 < \infty \quad \text{a$.$s$.$.}\] 
    %
\end{lemma}

\begin{lemma}
	\label{lem:basic bounds}
	Let the assumptions \ref{A1}--\ref{A2} and \ref{B1}--\ref{B2} be satisfied and let the sequences $\revise{\{\sx^k\}_{k\in\N}}$, $\revise{\{\sz^k\}_{k\in\N}}$ be generated by $\NSGD$. Let $0 \leq m<n$ be given with $\tau_{m,n} < \lambda$. Then, the following two bounds are valid:
    \begin{enumerate}[label=\textup{\textrm{(\alph*)}},leftmargin=3em,topsep=2pt,itemsep=.5ex,partopsep=0ex]
    \item It holds that $\norm{\Fnor(\sz^n)}^2 \leq  ({1-\frac{\tau_{m,n}}{2\lambda}})\norm{\Fnor(\sz^m)}^2 - \frac{2}{\lambda}\iprod{\su^{m,n}}{\sx^n-\sx^m} + [({\sL+\frac{1}{\lambda}})^2 + \frac{2\lambda \sL^2}{\tau_{m,n}}] \norm{\sx^n-\sx^m}^2 + \frac{3}{2\lambda\tau_{m,n}} \norm{\scp^{m,n}}^2$.
    \item We have $\psi(\sx^n) \leq \psi(\sx^m) + ({\frac{\sL}{2}-\frac{1}{\lambda}})\norm{\sx^n-\sx^m}^2 + \iprod{\su^{m,n}}{\sx^n-\sx^m}.$	
    \end{enumerate}
\end{lemma}

\begin{proposition}[Approximate descent property]
\label{lem:merit-descent-1}
Let \ref{A1}--\ref{A2} and \ref{B1}--\ref{B2} hold and let $\revise{\{\sz^k\}_{k\in\N}}$ be generated by $\NSGD$. Suppose, \revise{for $0\leq m <n$, the} step sizes $\revise{\{\alpha_k\}_{k\in\N}}$ satisfy $\tau_{m,n} = {\sum}_{i=m}^{n-1}\alpha_i\leq \frac{\sqrt{\xi}}{8\Llambda}$ where $\Llambda := \sL+\frac{2}{\lambda}$. We then have{}%\vspace{-2ex}
%
\begin{equation}
    H(\sz^n) - H(\sz^m) \leq  -\frac{\xi\tau_{m,n}}{8} \norm{\Fnor(\sz^m)}^2 + \frac{8}{\tau_{m,n}} \scs_{m,n}^2.
\end{equation}
\end{proposition}

\begin{proof}
By \cref{lem:basic bounds} and setting $\tau = \tau_{m,n}$, $\su = \su^{m,n}$, $\scp = \scp^{m,n}$, and $\scs = \scs_{m,n}$, it holds that
%
\begin{align}
 \nonumber   H(\sz^n) - H(\sz^m) & \leq  -\frac{\xi\tau}{4} \norm{\Fnor(\sz^m)}^2 + (1-\xi) \iprod{\su}{\sx^n-\sx^m} + \frac{3\xi}{4\tau} \norm{\scp}^2\\
 \label{H-descent1}   &\hspace{4ex} + \Big[{\Big({\frac{\sL}{2}-\frac{1}{\lambda}}\Big) + \frac{\xi\lambda}{2} \Big({\sL+\frac{1}{\lambda}}\Big)^2 + \frac{\xi \lambda^2\sL^2}{\tau}}\Big] \norm{\sx^n-\sx^m}^2.
\end{align}
%
Invoking the upper bound for $\iprod{\su}{\sx^n-\sx^m}$ in \cref{u-descent}, this yields 
%
\begin{align}
\nonumber    H(\sz^n) - H(\sz^m) & \leq -\frac{\xi\tau}{4} \norm{\Fnor(\sz^m)}^2 + \frac{4-\xi}{4\tau}\norm{\scp}^2\\
\label{H-descent2}    &\hspace{-6ex} + \underbracket{\Big[\frac{\sL}{2}-\frac{\xi}{\lambda} + \frac{\xi\lambda}{2} \Big({\sL+\frac{1}{\lambda}}\Big)^2 + \frac{4\xi \lambda^2\sL^2 - 3(1-\xi)}{4\tau}\Big]}_{=:T_1} \norm{\sx^n-\sx^m}^2.
\end{align}
%
Next, we bound $T_1$. Using $\xi= {(2+2\lambda^2\sL^2)^{-1}}$ and $(a+b)^2 \leq 2(a^2+b^2)$, $a,b \in \R$, we have $\frac12\xi\lambda(\sL+\lambda^{-1})^2 \leq \xi \lambda (\sL^2+\lambda^{-2}) = \frac{1}{2\lambda}$ and $4\xi \lambda^2\sL^2 - 3(1-\xi) \leq 4\xi(\lambda^2\sL^2+1)-3 = -1$. Applying the bound $\tau \leq \frac{\sqrt{\xi}}{8\Llambda} \leq \frac{1}{2(\sL+\lambda^{-1})}$, we then obtain $T_1 \leq \frac{\sL+\lambda^{-1}}{2} - \frac{\xi}{\lambda} - \frac{1}{4\tau} \leq - \frac{\xi}{\lambda} < 0$. Therefore, due to $\frac{4-\xi}{4\tau}\leq \frac{1}{\tau}$, the estimate \cref{H-descent2} simplifies to
%
\[
H(\sz^n) - H(\sz^m) \leq  -{(\xi\tau/4)} \norm{\Fnor(\sz^m)}^2 + {\tau^{-1}} \norm{\scp}^2.
\]
%
By \cref{lem:est-err}, we further have $\|\scp\|^2 \leq 8\Llambda^2 \tau^4 \|\Fnor(\sz^m)\|^2+8\scs^2$. This implies
%
\begin{align*}
    H(\sz^n) - H(\sz^m) \leq  - \Big[\frac{\xi}{4} - 8\Llambda^2 \tau^2 \Big]\tau\|{\Fnor(\sz^m)}\|^2 + \frac{8\scs^2}{\tau} 
    \leq  -\frac{\xi\tau}{8} \norm{\Fnor(\sz^m)}^2 + \frac{8\scs^2}{\tau} ,
\end{align*}
%
where the last inequality is again due to $\tau \leq \frac{\sqrt{\xi}}{8\Llambda}$.
\end{proof}

\begin{lemma}\label{lem:exist time}
Let $\sT > 0$, $\delta \in (0,1)$ be given. The following assertions are valid.
%
 \begin{enumerate}[label=\textup{\textrm{(\alph*)}},leftmargin=3em,topsep=0pt,itemsep=.5ex,partopsep=0ex]
 \item Assume $\alpha_k \in (0,(1-\delta) \sT]$, $k< K$, and $\alpha_k = \alpha \in(0,(1-\delta)\sT]$ for all $k \geq K$ and some $K\in\N$. We then have $t_k \to \infty$ and $\delta\sT \leq \tau_{t_k,t_{k+1}} \leq \sT$ for all $k \in\N$.

 \item
    If $\lim_{k\to\infty}\alpha_k = 0$ and $\sum_{k=0}^\infty \alpha_k = \infty$, it holds that $t_k \to \infty$ and $\delta \sT \leq \tau_{t_k,t_{k+1}} \leq \sT$ for all $k\in\N$.
    \end{enumerate}
\end{lemma}

\begin{proof} 
Here, we use the convention $\sup \emptyset = -\infty$. According to the construction of $\revise{\{t_k\}_{k\in\N}}$ in \cref{def:time win} and $\alpha_k \leq (1-\delta) \sT$, we have $t_0 = 0$ and $t_{k+1}=\varpi(t_k) \neq -\infty$ for all $k\in\N$. Furthermore, we have $t_{k+1} \neq \infty$ since $\sum_{k=0}^{\infty} \alpha_k = \infty$ implies $\tau_{t_k,n}\rightarrow \infty$ as $n\rightarrow \infty$. This also yields $t_{k} \to \infty$, i.e., $\revise{\{t_k\}_{k\in\N}}$ is an infinite subsequence.  By the definition of $\varpi(k)$, it follows $\tau_{t_k,t_{k+1}} =  \tau_{t_k,\varpi(t_{k})} \leq \sT$. In addition, by the optimality of $\varpi(t_k)$, we obtain $\tau_{t_k,t_{k+1}} =  \tau_{t_k,\varpi(t_{k})} \geq \sT - \alpha_{\varpi(t_k)} \geq \delta \sT$ for all $k$.
% 
We continue with part (b). Due to $\alpha_k \to 0$ and the definition of $t_0$, we have $\alpha_k \leq (1-\delta)\sT$ for all $k\geq  t_0$. Hence, all previous derivations are applicable in this case.
\end{proof}

\begin{lemma}\label{lem:index-time bound}
    Let \ref{A1}--\ref{A2} and \ref{B1}--\ref{B2} hold and let $\revise{\{\sx^k\}_{k\in\N}}$ and $\revise{\{\sz^k\}_{k\in\N}}$ be generated by $\NSGD$. Recalling $\Llambda := \sL+2\lambda^{-1}$, we have for all $i>t_0$:
%
    \begin{subequations}
    \begin{align}
    \label{eq:tech1}\|\Fnor(\sz^i)\|^2 &\leq 2\prt{2\Llambda\sT +1}^2\| \Fnor(\sz^{t_{\fk(i)}})\|^2 + 8\Llambda^2 \sr_{\fk(i)}^2, \\
    \label{eq:tech2}\psi(\sx^i) &\leq \psi(\sx^{t_{\fk(i)}})+(4\Llambda\sT^2+{\lambda}/{4})\norm{\Fnor(\sz^{t_{\fk(i)}})}^2 + 4\Llambda \sr_{\fk(i)}^2,\\
    \label{eq:tech3}\psi(\sx^i) &\geq \psi(\sx^{t_{\fk(i)+1}})-(4\Llambda\sT^2+{\lambda}/{4})\norm{\Fnor(\sz^{t_{\fk(i)}})}^2 - 16\Llambda \sr_{\fk(i)}^2.
\end{align}
 \end{subequations}
\end{lemma}

\begin{theorem}[Global convergence]
\label{thm:global_convergence-2}
Let \ref{A1}--\ref{A2}, \ref{B1}--\ref{B3} hold and let $\revise{\{\sx^k\}_{k\in\N}}$, $\revise{\{\sz^k\}_{k\in\N}}$ be generated by $\NSGD$. Then, there is $\spsi^* : \Omega \to \R$ such that: 
%
 \begin{enumerate}[label=\textup{\textrm{(\alph*)}},leftmargin=3em,topsep=0.5ex,itemsep=.5ex,partopsep=0ex]
        \item $\Fnor(\sz^k)\to 0$, $\|\partial \psi(\sx^k)\|_{-} \to 0$, and $\psi(\sx^k)\to \spsi^*$ a.s..
	\item $\Exp[\norm{\Fnor(\sz^k)}^2]\to 0$, $\Exp[\|\partial \psi(\sx^k)\|_{-}^2]\to0$, and $\Exp[\psi(\sx^k)] \to \Exp[\spsi^*]$.
\end{enumerate}
\end{theorem}

\begin{proof}
By \cref{lem:merit-descent-1}, \cref{lem:exist time} (b) (with $\delta = 4/5$; cf$.$ \cref{eq:def delta and T}), we have 
%
\begin{equation}
    \label{eq:thm:global-1}
    \mer(\sz^{t_{k+1}}) - \mer(\sz^{t_{k}}) \leq -\frac{\xi\sT}{{10}}\|\Fnor(\sz^{t_k})\|^2 + \frac{10}{\sT}\cdot\sr_{k}^2\quad \forall \,k\in\N.
\end{equation}
%
The condition $\sum_{k=0}^{\infty}\alpha_k^2\sigma_k^2<\infty$ and \cref{lem:err_estimate} imply that ${\sum}_{k=0}^\infty \sr_{k}^2<\infty$ a$.$s$.$ and ${\sum}_{k=0}^\infty\Exp[{\sr_{k}^2}]<\infty$. Setting $\su_k:=\frac{10}{\sT}\, \sum_{i=k}^\infty \sr_{i}^2$, it follows
%
\begin{equation}
	\label{eq:strong-0}
	\mer(\sz^{t_{k+1}}) + \su_{k+1} \leq  \mer(\sz^{t_{k}}) + \su_{k}- ({\xi \sT}/{10}) \|\Fnor(\sz^{t_k})\|^2.
\end{equation}	
%
Summing \cref{eq:thm:global-1} for $k=0,1,\ldots$ and using the bound $\mer(z)\geq \bar \psi$, this yields
%
\begin{equation}\label{eq:norm-sum}
{\xi\sT}\,{\sum}_{k=0}^\infty \|\Fnor(\sz^{t_k})\|^2 \leq 10[\mer(\sz^{t_{0}}) + \su_{0} - \bar \psi].
\end{equation}
%
Hence, due to ${\sum}_{k=0}^\infty \sr_{k}^2<\infty$ a$.$s$.$, we can conclude $\|\Fnor(\sz^{t_k})\|\to 0$, $\sr_{k}\to0$, and $\su_{k}\to0$ a$.$s$.$. Moreover, based on the definition \cref{index-def} of $\fk(i)$, we can infer $\|\Fnor(\sz^{t_{\fk(i)}})\|\to 0$ and $\sr_{\fk(i)}\to0$ as $i\to\infty$ a$.$s$.$. This proves $\|\Fnor(\sz^{i})\|\to 0$ a$.$s$.$ owing to \cref{eq:tech1}. 

Taking expectation in \cref{eq:norm-sum} and using $\sum_{k=0}^\infty\Exp{[\sr_{k}^2]}<\infty$, we further obtain $\Exp[\sr_{k}^2]\to0$, $\Exp[\su_{k}^2]\to0$, and $\Exp[{\|\Fnor(\sz^{t_k})\|^2}]\to 0$. Thus, we can infer $\Exp[\|\Fnor(\sz^{i})\|^2]\to 0$ by taking expectation in \cref{eq:tech1} and passing $i\to\infty$. By \cref{eq:stat-am}, we have $\|\partial \psi(\proxl(z))\|_{-} \leq \|\Fnor(z)\|$, which implies $\|\partial \psi(\sx^k)\|_{-} \to 0$ a$.$s$.$ and $\Exp[{\|\partial \psi(\sx^k)\|^2_{-}}] \to 0$.

Next, we show $\psi(\sx^{t_k}) \to \spsi^*$ a$.$s$.$. By \cref{eq:strong-0}, $\{\mer(\sz^{t_k})+\su_k\}_k$ is monotonically non-increasing, and thus, we conclude that $\mer(\sz^{t_k})+\su_k \to \spsi^*$ a$.$s$.$ for some random variable $\spsi^*$. Using $\|\Fnor(\sz^{t_k})\|\to0$, $\su_k\to 0$, and $\psi(\sx^{t_k}) = \mer(\sz^{t_k}) + \su_k - (\frac{\xi\lambda}{2}\|\Fnor(\sz^{t_k})\|^2+\su_k)$, we obtain $\psi(\sx^{t_k}) \to \spsi^*$ a$.$s$.$. Taking $i\to \infty$ in \cref{eq:tech2} and \cref{eq:tech3}, it follows %
\begin{align*}
     \psi(\sx^i) &\leq \psi(\sx^{t_{\fk(i)}})+(4\Llambda\sT^2+\lambda/4)\norm{\Fnor(\sz^{t_{\fk(i)}})}^2 + 4\Llambda \sr_{\fk(i)}^2 \to \spsi^*,\\
    \psi(\sx^i) &\geq \psi(\sx^{t_{\fk(i)+1}})-(4\Llambda\sT^2+\lambda/4)\norm{\Fnor(\sz^{t_{\fk(i)}})}^2 - 16\Llambda \sr_{\fk(i)}^2 \to \spsi^*, \quad \text{a.s.},
 \end{align*}
%
and hence $\psi(\sx^i) \to \spsi^*$. Finally, we verify $\Exp[\psi(\sx^{i})] \to \Exp[\spsi^*]$. Since $\{\mer(\sz^{t_k}) + \su_k\}_k$ is bounded below by $\bar\psi$, non-increasing, and converges to $\spsi^*$, we can obtain $\Exp[\mer(\sz^{t_k}) + \su_k]\to \Exp[\spsi^*]$ by the monotone convergence theorem. Using similar arguments as before, this yields $\Exp[\psi(\sx^{t_k})] \to \Exp[\spsi^*]$. Let us now define $\ssigma_i := \psi(\sx^{t_{\fk(i)}})+(4\Llambda\sT^2+\lambda/4)\norm{\Fnor(\sz^{t_{\fk(i)}})}^2 + 4\Llambda \sr_{\fk(i)}^2$.
%
We then have $\psi(\sx^i) \leq \ssigma_i$ (see \cref{eq:tech2}), $\ssigma_i\to \spsi^*$ a$.$s$.$, and $\Exp[\ssigma_i]\to \Exp[\spsi^*]$. Applying Fatou's Lemma for $\psi(\sx^i)-\bar{\psi}$ and $\ssigma_i-\psi(\sx^i)$, it follows 
%
 \begin{align*}
      \Exp[\spsi^*]-\bar{\psi} &= \Exp[{{\lim}_{i\to\infty}({\psi(\sx^i)-\bar{\psi}}})] \leq {\liminf}_{i\to\infty}{\Exp{[\psi(\sx^i)]}}-\bar{\psi}\quad 
 \end{align*}
%
and $0 = \Exp[{{\lim}_{i\to\infty} (\ssigma_i-\psi(\sx^i))}] \leq \Exp[{\spsi^*}] - {\limsup}_{i\to\infty} {\Exp{[\psi(\sx^i)]}}$. Consequently, we can infer $\Exp{[\psi(\sx^i)]}\to \Exp[{\spsi^*}]$. This finishes the proof. 
\end{proof}

\begin{lemma}[Kurdyka-{\L}ojasiewicz-type inequality]
\label{lem:KL-mer}
    Let \ref{A3} hold and let $\bar z$ be given with $\bar{x}=\proxl(\bar{z}) \in \crit(\psi)$. For all $\theta\in[\frac12,1)$, there then are $\varsigma, \rho > 0, \eta\in(0,1]$ and a continuous, concave function $\varrho:[0,\eta) \to \R_+$, which is $C^1$ on $(0,\eta)$, satisfying 
      \begin{enumerate}[label=\textup{\textrm{(\alph*)}},leftmargin=3em,topsep=1pt,itemsep=.5ex,partopsep=0ex]
         \item $1/\varrho^\prime(s+t) \leq 1/\varrho^\prime(s) + \varsigma t^{\theta}$ for all $s,t >0$ with $s+t<\eta$,
         \item $\varrho(0) = 0$ and $\varrho^\prime(t) \geq t^{-\theta}$ for all $t\in(0,\eta)$,
     \end{enumerate}
     such that, for all $z\in\cB_\rho(\bar z) \cap\{z:0<|\mer(z)-\mer(\bar z)| + \frac{\xi\lambda}{2}\|\Fnor(z)\|^2<\eta\}$, we have
     \begin{equation}
         \label{eq:mer-kl}
         \varrho^\prime(|\mer(z)-\mer(\bar z)|) \cdot  \|\Fnor(z)\|\geq 1.
     \end{equation} 
\end{lemma}

\begin{proof}
The proof is divided into two steps. First, we show that $\psi$ satisfies the KL property, with the desingularization function $\varrho$ being concave, differentiable, and fulfilling properties (a) and (b). This step closely follows the proof of \cite[Lemma 4.11]{josz2024proximal}. Although the differences are minor, we include a complete proof for self-containedness. In the second step, we show that these properties can be transferred to $\mer$. %\\[1mm]

\noindent\textbf{Step 1.}  
%
Applying \cite[Corollary 15]{boldanlewshi07} and \cite[Theorem 4.1]{AttBolRedSou10}, there are $\rho,\eta_1 >0$ and a definable, concave, continuous function $\varrho_1:[0,\eta_1)\to\R_+$, $\varrho_1 \in C^1((0,\eta_1))$, such that 
%
\begin{equation}
\varrho_1^\prime(|\psi(x)-\psi(\bar x)|) \cdot \|\partial \psi(x)\|_{-}\geq 1, \quad \forall\; x\in\cB_{\rho}(\bar x) \cap\{x:0<|\psi(x)-\psi(\bar x)|<\eta_1\}. \label{eq:kl-1}
\end{equation}
%
We now set $\varrho(t)=\int_{0}^t \varrho^\prime(\tau)\,\rmd \tau$, $\varrho^\prime(t):=\max\{\varrho_1^\prime(t),t^{-\theta}\}$, and $\bar \eta:=\min\{\eta_1,1\}$. Then, $\varrho(0)=0$ and \cref{eq:kl-1} remains to hold with $\varrho_1$ and $\eta_1$ being replaced by $\varrho$ and $\bar \eta$, respectively.
The function $\varrho$ is continuous, $C^1$ on $(0,\bar\eta)$, and concave as $\varrho^\prime$ is non-increasing. 
%
Moreover, $\varrho^\prime$ is definable because $t \mapsto t^{-\theta}$ and $\varrho_1^\prime$ are definable \cite[Lemma 6.1]{coste2000introduction}, so is $t\mapsto 1/\varrho^\prime(t)$ \cite[Lemma 2.3 p.14]{van1998tame} (see also \cite[Section 4.3]{AttBolRedSou10}). According to \cite[Theorem 6.4]{coste2000introduction}, the mapping $t\mapsto 1/\varrho^\prime(t)$ is differentiable for all but finitely many points in $(0,\bar \eta)$. This result, along with the monotonicity theorem \cite[(1.2) p.43]{van1998tame}, indicates that $t\mapsto 1/\varrho^\prime(t)$ is differentiable and monotone on the interval $(0,\eta)$ for some $\eta\in(0,\bar \eta)$.  

If $(1/\varrho^\prime)^\prime(t)\to \infty$ as $t\searrow0$, then $(1/\varrho^\prime)^\prime$ is decreasing on $(0,\eta)$ and $1/\varrho^\prime$ is concave. By \cite[Lemma 3.5]{josz2023convergence}, this yields $1/\varrho^\prime(s+t) \leq 1/\varrho^\prime(s) + 1/\varrho^\prime(t) \leq 1/\varrho^\prime(s) + t^\theta$ for all $s,t>0$ and $s+t<\eta$. Otherwise, we have $\bar\varsigma:=\max_{\tau\in(0,\eta)}(1/\varrho^\prime)^\prime(\tau) < \infty$ and by the mean value theorem, it follows $1/\varrho^\prime(s+t) - 1/\varrho^\prime(s)= (1/\varrho^\prime)^\prime(\tau) t \leq \bar\varsigma t \leq \bar\varsigma t^{\theta}$, $\tau \in (0,\eta)$, where we used $\theta < 1$ and $t \in (0,1)$. Note that $\bar\varsigma$ is nonnegative since $(1/\varrho^\prime)^\prime(\tau) = -\varrho^{\prime\prime}(\tau)/(\varrho^\prime(\tau))^2 \geq 0$ (by the concavity of $\varrho$). We may now set $\varsigma := \max\{\bar\varsigma,1\}$. %\\[1mm]

\noindent\textbf{Step 2:} \emph{Property \cref{eq:mer-kl} for $\mer$.} Let $z\in\cB_\rho(\bar z) \cap\{z:0<|\mer(z)-\mer(\bar z)|+ \frac{\xi\lambda}{2}\|\Fnor(z)\|^2<\eta\}$ be arbitrary. Setting $x=\proxl(z)$ and using the nonexpansiveness of $\proxl$, we have $\|x-\bar x\| \leq \|z-\bar z\| \leq \rho$ and $|\psi(x)-\psi(\bar x)| \leq |\mer(z)-\mer(\bar z)|+ \frac{\xi\lambda}{2}\|\Fnor(z)\|^2<\eta$.

Thus, if $x$ satisfies $\psi(x) \neq \psi(\bar x)$, then \textbf{Step 1} implies $\varrho^\prime(|\psi(x)-\psi(\bar x)|) \|\partial \psi(x)\|_{-}\geq 1$. Furthermore, since $1/\varrho^\prime$ is non-decreasing and applying the bound (a), we can infer
%
\begin{align*}
          1/\varrho^\prime(|\mer(z)-\mer(\bar z)|) 
          &\leq  1/\varrho^\prime(|\psi(x)-\psi(\bar x)| + \tfrac{\xi\lambda}{2}\|\Fnor(z)\|^2)\\
          &\leq 1/\varrho^\prime(|\psi(x)-\psi(\bar x)|) + \varsigma (\tfrac{\xi\lambda}{2}\|\Fnor(z)\|^2)^\theta \\ &\leq \|\partial \psi(x)\|_{-} + \varsigma \sqrt{\xi\lambda/2}\|\Fnor(z)\| \leq (1+\varsigma \sqrt{\xi\lambda/2})\|\Fnor(z)\|.
\end{align*}
%
Here, the third inequality is due to $\tfrac{\xi\lambda}{2}\|\Fnor(z)\|^2<1$ and $\theta\in[\frac12,1)$, and the last step follows from $\Fnor(z)\in\partial \psi(x)$. If $\psi(x) = \psi(\bar x)$, then we obtain $1/\varrho^\prime(|H(z)-H(\bar z)|) \leq (\tfrac{\xi\lambda}{2}\|\Fnor(z)\|^2)^\theta \leq \sqrt{\xi\lambda/2}\|\Fnor(z)\|$ by (b). We can conclude the proof after rescaling $\varrho$ to $(1+\max\{1,\varsigma\} \sqrt{\xi\lambda/2}) \varrho$ (this does not affect the properties (a)--(b)).
\end{proof}

\subsubsection{\texorpdfstring{Proof of \cref{thm:iter converge}}{Proof of Theorem 4.2}}

We start the proof by deriving certain summability results for the error terms $\su_k$ and $\sr_k$. %\\[1mm]

\noindent\textbf{Step 1:} \emph{Summability of error terms.} Due to condition \cref{eq:kl-step} (i.e., $\sum_{k=0}^\infty \alpha_k^2 \tau_{0,k}^{\mu}\sigma_k^2  <\infty$) and \cref{lem:err_estimate}, we have $\bar \sr:=\sum_{k=0}^\infty \tau_{0,t_k}^{\mu}\sr_k^2<\infty$ a$.$s$.$. This yields \vspace{-0.5ex}
\[
\sT\su_k = {10}\, {\sum}_{i=k}^\infty \sr_{i}^2 =  {10}\, {\sum}_{i=k}^\infty \tau_{0,t_i}^{-\mu} \tau_{0,t_i}^{\mu} \sr_{i}^2 \leq {10} \tau_{0,t_k}^{-\mu} \cdot {\sum}_{i=k}^\infty  \tau_{0,t_i}^{\mu} \sr_{i}^2 \leq {10\bar \sr}  \cdot \tau_{0,t_k}^{-\mu}.
\]
%
Using $\delta \sT \leq \tau_{t_k,t_{k+1}}$, it follows $\tau_{0,t_k} \geq  \tau_{0,t_0} + \delta \sT k$ and $\su_k\to 0$ a$.$s$.$, which implies 
%
\begin{equation}
    \label{eq:summability u_k}
    {\sum}_{k=0}^\infty \su_k^\theta \leq (10\bar\sr/\sT)^\theta  \cdot {\sum}_{k=0}^\infty (\tau_{0,t_0} + \delta \sT k)^{-\mu\theta}<\infty \quad \text{for all}\quad \theta > \tfrac{1}{\mu}.
\end{equation}
%
Hence, we have $\sum_{k=j}^\infty \su_k^\theta \to 0$ as $j\to\infty$ for all $\theta > {\mu}^{-1}$. Moreover, it holds that \vspace{-1ex}
%
\begin{equation}\label{eq:rk-sum}
{\sum}_{k=0}^\infty \sr_k = {\sum}_{k=0}^\infty \tau_{0,t_k}^{-\frac{\mu}{2}}\cdot \tau_{0,t_k}^{\frac{\mu}{2}} \sr_k \leq \Big({ \bar{\sr} \cdot {\sum}_{k=0}^\infty (\tau_{0,t_0} + \delta \sT  k)^{-\mu} }\Big)^{1/2} < \infty \quad \text{a$.$s$.$.}
\end{equation}
%
Let us fix $\theta\in(\max\{\frac{1}{\mu},\frac12\},1)$ and let us introduce the events $\mathcal E := \{\omega : \sum_{k=0}^\infty \su_k(\omega)^\theta < \infty, \, \sum_{k=0}^\infty \sr_k(\omega) < \infty\}$ and $\mathcal C := \mathcal X \cap \{\omega : \Fnor(\sz^k(\omega)) \to 0, \, \psi(\sx^k(\omega))\to\spsi^*(\omega)\}$. Condition \cref{eq:kl-step} implies that \ref{B3} is satisfied. Thus, by \cref{thm:global_convergence-2}, \cref{eq:summability u_k}, \cref{eq:rk-sum}, and \ref{B4}, we can infer $\Prob(\mathcal C) = \Prob(\mathcal E) = \Prob(\mathcal D)=1$, where $\mathcal D = \mathcal C \cap \mathcal E$. %\\[1mm]

\noindent\textbf{Step 2:} \emph{Subsequence convergence and roadmap.} We first present an auxiliary result.

\begin{lemma}[Subsequence convergence]\label{lem:subsequence converge}
Let \ref{A1}--\ref{A2} and \ref{B1}--\ref{B4} hold and let $\omega\in\mathcal C$ be arbitrary. Then, there exist $z^*\in\Rn$ and a subsequence $\revise{\{q_k\}_{k\in\N}}\subseteq \N$ such that $x^*:=\proxl(z^*)\in\crit(\psi)$, $x^{q_k} \to x^*$, $z^{q_k} \to z^*$, $\psi(x^k) \to \psi(x^*) = \psi^*$, and $\mer(z^{k}) \to \mer(z^*) = \psi^*$ as $k\to\infty$, where  
$\revise{\{x^k\}_{k\in\N}} = \revise{\{\sx^k(\omega)\}_{k\in\N}}$ and $\revise{\{z^k\}_{k\in\N}}= \revise{\{\sz^k(\omega)\}_{k\in\N}}$. 
\end{lemma}

The proof of \cref{lem:subsequence converge} can be found in \cref{proof:lem:subsequence converge}. To simplify the notation, we set
%
$\sd_k := {\max}_{t_k<i\leq t_{k+1}} \max\{\|\sx^i-\sx^{t_k}\|,\|\sz^i-\sz^{t_k}\|\}$.

\cref{lem:est-err} and $\tau_{t_k,t_{k+1}} \leq \sT$ then imply 
%
\begin{equation}\label{dk-bound}
    % \sd_k^2 \leq 4 \sT^2 \|\Fnor(\sz^{t_k})\|^2 + 4 \sr_k^2.
    \sd_k \leq 2 \sT \|\Fnor(\sz^{t_k})\| + 2 \sr_k.
\end{equation}
%
Our goal is to show $\sx^k \to \sx^*$ a$.$s$.$. Thanks to $\Prob(\mathcal D)=1$, it suffices to prove that $\revise{\{\sx^k(\omega)\}_{k\in\N}}$ is a Cauchy sequence for all $\omega \in \mathcal D$. Let $\omega \in \mathcal D$ be arbitrary and let $\revise{\{x^k\}_{k\in\N}} = \revise{\{\sx^k(\omega)\}_{k\in\N}}$,  $\revise{\{z^k\}_{k\in\N}} = \revise{\{\sz^k(\omega)\}_{k\in\N}}$, $\revise{\{r_k\}_{k\in\N}} = \revise{\{\sr_k(\omega)\}_{k\in\N}}$, etc. denote the corresponding realizations. For given $\varepsilon>0$, we need to show that there is $k$ such that $\|x^m - x^n\|<\varepsilon$ for all $k\leq m<n$. 

We claim that it suffices to establish ${\sum}_{k=0}^{\infty}\,d_k< \infty$. In this case, there is $k^\prime\in\N$ such that ${\sum}_{j=k}^{\infty}\,d_j<\varepsilon/2$ for all $k \geq k^\prime$. For any $n > m > t_{k^\prime}$, we have $k^\prime \leq \fk(m)\leq \fk(n)$. Therefore, using the triangle inequality and the above bound, we obtain %\vspace{-1.5ex}
%
\begin{equation*}
\|x^m - x^n\| \leq d_{\fk(m)} + d_{\fk(n)} + {\sum}_{j=\fk(m)}^{{\fk(n)-1}}\|x^{t_{j+1}}-x^{t_j}\| \leq 2 {\sum}_{j=\fk(m)}^{{\fk(n)}} d_j< \varepsilon, 
\end{equation*}
%
which proves our claim. In the remaining steps, we establish summability of $\revise{\{d_k\}_{k\in\N}}$.%\\[1mm]

\noindent\textbf{Step 3:} \emph{Entering the local region and a KL-based bound for $\revise{\{d_k\}_{k\in\N}}$.} By \cref{lem:subsequence converge}, there exists a subsequence $\revise{\{q_k\}_{k\in\N}}$ such that $x^{q_k} \to x^*$, $z^{q_k} \to z^*$ for some $z^*$ with $x^* = \proxl(z^*) \in\crit(\psi)$, and $\mer(z^{k}) \to \mer(z^*) = \psi^*$. Based on the definition of $\fk$ and $d_k$, it holds that $\max\{\|x^{q_k} - x^{t_{\fk(q_k)}}\|,\|z^{q_k} - z^{t_{\fk(q_k)}}\|\} \leq d_{\fk(q_k)}$. Due to $\|\Fnor(z^{t_{{\fk(q_k)}}})\|\to0$, $r_{{\fk(q_k)}}\to0$, and \cref{dk-bound}, we then have $d_{{\fk(q_k)}} \to 0$, $x^{t_{\fk(q_k)}} \to x^*$, and $z^{t_{\fk(q_k)}} \to z^*$.


Applying \cref{lem:KL-mer}, there exist $\rho>0$, $\eta\in(0,1]$, and a concave function $\varrho:[0,\eta)\to\R_+$, $\varrho \in C^1((0,\eta))$ (satisfying properties (a)--(b) in \cref{lem:KL-mer}) such that
%
\begin{equation}
         \label{eq:super-proof-kl}
         \varrho^\prime(|\mer(z)-\psi^*|) \cdot  \|\Fnor(z)\|\geq 1\quad %\text{holds}
\end{equation}
%
for all $z\in\cB_\rho(z^*) \cap\{z \in \Rn:0<|\mer(z)-\psi^*| + \frac{\xi\lambda}{2}\|\Fnor(z)\|^2<\eta\}$.

Next, we define $\Delta_k:= \varrho(\mer(z^{t_k}) -\psi^* + u_k)$.
Since \revise{$\{\mer(z^{t_k}) -\psi^* + u_k\}_{k \in \N}$} is monotonically decreasing (see \cref{eq:strong-0}) with $\mer(z^{t_k}) + u_k \to \psi^*$, $\Delta_k$ is well-defined. By $\omega \in \mathcal D$, $\varrho(0) = 0$, and by the previous discussion, there then is $\hat k \in \N$ such that
%
\begin{subequations}
\label{eq:choose rho eta}
    \begin{align}
        \label{eq:choose rho eta-1} &\|z^{t_{\hat k}} - z^*\| + 20\xi^{-1}\Delta_{\hat{k}}  + 2\varsigma\sT {\sum}_{i=\hat k}^\infty\, u_i^\theta + 2{\sum}_{i=\hat k}^\infty\, r_i< \rho \quad \text{and} \quad \\ \label{eq:choose rho eta-2} &|\mer(z^{t_k})-\psi^*| + \max\{\tfrac{\xi\lambda}{2}\|\Fnor(z^{t_k})\|^2, u_k\} \leq  \eta\quad\text{for all} \quad k \geq \hat k. 
    \end{align}
\end{subequations}

Let $k \geq \hat k$ be now given with $z^{t_k} \in \mathcal B_\rho(z^*)$. (In particular, this is true for $k = \hat k$). Hence, by \cref{eq:choose rho eta-2}, the KL inequality \cref{eq:super-proof-kl} is applicable and we have
%
\begin{subequations}
    \begin{align}
	\label{eq:long-equation-1}\Delta_k - \Delta_{k+1}
    & \geq \varrho^\prime(\mer(z^{t_k}) - \psi^*+u_k)(\mer(z^{t_k}) +u_k - [\mer(z^{t_{k+1}})+u_{k+1}]) \\
	\label{eq:long-equation-2}& \geq \varrho^\prime(|\mer(z^{t_k}) - \psi^*|+u_k) (\xi \sT \|\Fnor(z^{t_k})\|^2/10) \\%[1mm]
	\label{eq:long-equation-3}&\geq (1/\varrho^\prime({|\mer(z^{t_k}) - \psi^*|})  + \varsigma u_k^\theta)^{-1} (\xi \sT \|\Fnor(z^{t_k})\|^2/10) \\
    \label{eq:long-equation-4}&\geq \frac{\xi\sT}{10}\cdot \frac{\|\Fnor(z^{t_k})\|^2}{\|\Fnor(z^{t_k})\| +  \varsigma u_k^\theta}\geq \frac{\xi \sT}{10}\srt{\|\Fnor(z^{t_k})\| -  \varsigma 
 u_k^\theta}.
\end{align}
\end{subequations}
%
The inequality \cref{eq:long-equation-1} is due to the concavity of $\varrho$, \cref{eq:long-equation-2} follows from the descent-type property \cref{eq:strong-0} and the fact that $\varrho^\prime$ is non-increasing, \cref{eq:long-equation-3} utilizes $\varrho^\prime(s+t) \geq [1/\varrho^\prime(s) + \varsigma t^{\theta}]^{-1}$ (see \cref{lem:KL-mer} (a)), and \cref{eq:long-equation-4} is based on \cref{eq:super-proof-kl} and ${a^2}\geq a^2-b^2$, $a,b\in \R$. Rearranging yields $\sT\|\Fnor(z^{t_k})\| \leq 10\xi^{-1}(\Delta_k - \Delta_{k+1}) + \varsigma \sT u_k^\theta$. Combining this estimate with $d_k \leq 2 \sT \|\Fnor(z^{t_k})\| + 2 r_k$ (see \cref{dk-bound}), we can infer
%
\begin{equation}
    \label{eq:d bound}
d_k \leq 20\xi^{-1}(\Delta_k - \Delta_{k+1}) + 2\varsigma\sT u_k^\theta + 2r_k.
\end{equation}

\noindent\textbf{Step 4:} \emph{Attracted by the local region.}  We now show that the following statements hold for all $k \geq \hat k$: 
%
	\begin{enumerate}[label=(\alph*),topsep=4pt,itemsep=0.5ex,partopsep=0ex]
	\item $z^{t_k} \in \mathcal{B}_{\rho}(z^*)$ and $|\mer(z^{t_k}) - \psi^*| + \max\{\frac{\xi\lambda}{2}\|\Fnor(z^{t_k})\|^2,u_k\}< \eta$.
 %\vspace{1mm}
	\item $\sum_{i=\hat k}^{k}d_i  \leq 20\xi^{-1}[\Delta_{\hat k} - \Delta_{k+1}] + 2\varsigma\sT \sum_{i=\hat k}^k u_i^\theta + 2\sum_{i=\hat k}^k r_i.$
	\end{enumerate}
% 
We will prove these statements by induction. First, (a) and (b) are satisfied for $k=\hat k$ thanks to \cref{eq:choose rho eta} and \cref{eq:d bound}. To conduct the induction step, let us assume that (a)--(b) hold for some $k =n \geq \hat k$. We first verify (a) for $k=n+1$. Due to \cref{eq:choose rho eta-2}, the bound $|\mer(z^{t_{n+1}}) - \psi^*| + \max\{\frac{\xi\lambda}{2}\|\Fnor(z^{t_{n+1}})\|^2,u_{n+1}\} < \eta$ is immediate. Moreover, we have
%
\begin{align*}
    \|z^{t_{n+1}} - z^*\| &\leq \|z^{t_{\hat k}} - z^*\| + {\sum}_{i=\hat{k}}^n \|z^{t_{i+1}} - z^{t_{i}}\| \leq  \|z^{t_{\hat k}} - z^*\| + {\sum}_{i=\hat k}^n \,d_i\\
    &\leq \|z^{t_{\hat k}} - z^*\| +  20\xi^{-1}[\Delta_{\hat k} - \Delta_{n+1}] + 2\varsigma\sT {\sum}_{i=\hat k}^\infty\, u_i^\theta + 2{\sum}_{i=\hat k}^\infty\, r_i < \rho,
\end{align*}
%
where the second inequality follows from the definition of $d_k$, the third step uses (b) for $k=n$, and the last step holds due to \cref{eq:choose rho eta-1} and $\Delta_{n+1}\geq 0$. Next, we prove that (b) holds for $k=n+1$. Invoking \cref{eq:d bound} with $k=n+1$ and (b) with $k=n$, we obtain
%
\[
{\sum}_{i=\hat k}^{n+1}\,d_i = d_{n+1} + {\sum}_{i=\hat k}^{n}\,d_i \leq 20\xi^{-1}[\Delta_{\hat k} - \Delta_{n+2}] + 2\varsigma\sT {\sum}_{i=\hat k}^{n+1}\, u_i^\theta + 2{\sum}_{i=\hat k}^{n+1}\, r_i.
\]
%
This completes the induction. Thus, (a), (b), and \cref{eq:d bound} hold for all $k \geq \hat k$. %\\[1mm]

\noindent\textbf{Step 5:} \emph{Summability of $\revise{\{d_k\}_{k\in\N}}$.} Taking $k\to\infty$ in \textbf{Step 4} (b) and due to $\Delta_k \geq 0$, we have \vspace{-1.5ex}
%
\begin{equation*} 
{\sum}_{i=\hat k}^{\infty}d_i  \leq 20\xi^{-1}\Delta_{\hat k} + 2\varsigma\sT {\sum}_{i=\hat k}^{\infty} u_i^\theta + 2{\sum}_{i=\hat k}^{\infty} r_i < \rho < \infty.
\end{equation*}
%
This yields $\sum_{k=0}^{\infty}d_k < \infty$ and, following \textbf{Step 2}, this completes the proof. \hfill \proofbox

\begin{proof} Let $\omega \in \Omega$ be arbitrary and let us set $\tau = \tau_{m,n}$, $p = p^{m,n} = \scp^{m,n}(\omega)$, $s = s_{m,n} = \scs_{m,n}(\omega)$, $x^k = \sx^k(\omega)$, $z^k = \sz^k(\omega)$, etc. It follows from the definition of $p^{m,i}$ \revise{and $s_{m,n}$} and the triangle inequality that
%
\begin{align}
        \nonumber \|p^{m,i}\| &\leq {\sum}_{j=m}^{i-1}\alpha_j\|{\Fnor(z^j) - \Fnor(z^m)}\| + \Big\|{{\sum}_{j=m}^{i-1} \alpha_j e^j}\Big\| \\ &\leq {\sum}_{j=m}^{i-1}\alpha_j\|{\Fnor(z^j) - \Fnor(z^m)}\| + s,\qquad \text{for all $i\in(m,n] \cap \N$.} \label{eq:lem-4-est-1}
\end{align}
% 
Recalling $\Fnor(z) = \nabla f(x) + \lambda^{-1}(z-x)$ and using \ref{A1} and the nonexpansiveness of the proximity operator (i.e., $\|x^i-x^m\| \leq \|z^i-z^m\|$), we have
%
\begin{equation}
\label{eq:nor is Lip}
     \|\Fnor(z^j) - \Fnor(z^m)\| \leq (\sL+\lambda^{-1})\|x^j-x^m\| + \lambda^{-1}\|z^j-z^m\| \leq  \Llambda \|z^j-z^m\|,% =: C_\lambda\|z^i-z^m\|.
\end{equation} 
%
where $\Llambda =\sL+2\lambda^{-1}$. Thus, combining the relation $z^i = z^m - \tau_{m,i}\Fnor(z^m) + p^{m,i}$ (cf$.$ \cref{eq:pretty-important})\revise{, $\tau_{m,i} \leq \tau$,} and the inequality \cref{eq:lem-4-est-1}, we can infer
% 
\begin{align}
    \nonumber \|z^i-z^m\| &\leq \tau_{m,i} \|\Fnor(z^m)\| + \|p^{m,i}\| \\
    \nonumber &\leq {\sum}_{j=m}^{i-1} \alpha_j \|\Fnor(z^j)-\Fnor(z^m)\| + \tau \|\Fnor(z^m)\| + s\\ 
    \label{eq:lem-4-est-3} &\leq \Llambda {\sum}_{j=m}^{i-1} \alpha_j  \|z^j-z^m\| + \tau \|\Fnor(z^m)\| + s, \qquad \text{for all $i\in(m,n] \cap \N$}.
\end{align}
%
We now apply Gronwall's inequality (\cref{Thm:G}) upon setting $b_1 :=\tau \|\Fnor(z^m)\| + s$, $b_2 := \Llambda$, $a_k:=\alpha_{m+k}$, $y_k:=\|z^{m+k} - z^m\|$, and $t:=i-m-1$. For all $i\in(m,n] \cap \N$, this establishes the following upper bound  
%
\begin{equation}
            \|z^i - z^m\|  \leq \exp(\tau \Llambda) \cdot [\tau\|\Fnor(z^m)\|+s]\leq 2\tau\|\Fnor(z^m)\| + 2s,
            \label{eq:lem-4-est-5}
\end{equation}
%
where the last inequality is due to $\tau\Llambda \leq \frac12$ and $\exp(\frac12)\leq 2$. Moreover, it follows from $\|x^i-x^m\| \leq \|z^i-z^m\|$ that ${\max}_{m<i\leq n}\|x^i-x^m\| \leq {\max}_{m<i\leq n}\|z^i-z^m\| \leq 2\tau\|\Fnor(z^m)\| + 2s$. This verifies the first bound in \cref{lem:est-err}. 

Next, combining \cref{eq:nor is Lip} and \cref{eq:lem-4-est-5}, we obtain
%
\[
{\max}_{m<i\leq n} \|\Fnor(z^i) - \Fnor(z^m)\|\leq \Llambda{\max}_{m<i\leq n}\|z^i-z^m\| \leq 2\Llambda[\tau\|\Fnor(z^m)\| + s].
\]
%
Using this bound in \cref{eq:lem-4-est-1} with $i=n$ and recalling $\tau={\sum}_{i=m}^{n-1} \alpha_i$, this yields $\|p\|\leq s+ 2\Llambda (\tau\|\Fnor(z^m)\| + s) {\sum}_{j=m}^{n-1} \alpha_j \leq 2\Llambda\tau^2\|\Fnor(z^m)\| + 2s$.
\end{proof}

\begin{proof}[Proof of (a)]
Let $\omega\in\Omega$ be arbitrary and denote $x^k = \sx^k(\omega)$, $z^k = \sz^k(\omega)$, $p = \scp^{m,n}(\omega)$, $u = \su^{m,n}(\omega)$, $\tau = \tau_{m,n}$, etc$.$. Recalling $\Fnor(z) = \nabla f(x) + \lambda^{-1}(z-x)$ and by the definition \cref{eq:u-def1} of $\su^{m,n}$, we can express $\Fnor(z^n)$ as
%
\begin{align*} 
    \Fnor(z^n) 
    & = \Fnor(z^m) + [\nabla f(x^n)-\nabla f(x^m)] + \lambda^{-1}\prt{z^n-z^m+x^m-x^n}\\
    & = u + [\nabla f(x^n)-\nabla f(x^m)] - \lambda^{-1}(x^n-x^m).
\end{align*}	
%
Taking squares and using the Lipschitz continuity of $\nabla f$, this yields
%
\begin{align}
            \nonumber \norm{\Fnor(z^n)}^2 & = \norm{u}^2 + 2\iprod{u}{(\nabla f(x^n)-\nabla f(x^m)) - \lambda^{-1}(x^n-x^m)} \\
            \nonumber&\hspace{4ex}  +  \norm{(\nabla f(x^n)-\nabla f(x^m)) - \lambda^{-1}(x^n-x^m)}^2\\
            \label{C1} & \hspace{-6ex} \leq \norm{u}^2 + 2\iprod{u}{(\nabla f(x^n)-\nabla f(x^m))-\lambda^{-1}(x^n-x^m)} + (\sL+{\lambda}^{-1})^2 \norm{x^n-x^m}^2.
\end{align}
%
Using $u=(1-\lambda^{-1}\tau)\Fnor(z^m) + \lambda^{-1}p$ (cf$.$ \cref{eq:u-def3}) and $\norm{a+b}^2 \leq (1+\varepsilon) \norm{a}^2 + (1+\frac{1}{\varepsilon})\norm{b}^2$ with $a= (1-\lambda^{-1}\tau) \Fnor(z^m)$, $b = \lambda^{-1}p$, and $\varepsilon = \frac{\lambda^{-1}\tau}{1-\lambda^{-1}\tau}$, we have
%
\begin{equation}\label{C2}
        \norm{u}^2 \leq (1-\lambda^{-1}{\tau}) \|{\Fnor(z^m)}\|^2 + (\lambda\tau)^{-1} \|{p}\|^2.
\end{equation}
%
Utilizing Young's inequality for $2\iprod{u}{\nabla f(x^n)-\nabla f(x^m)}$ and \cref{C2}, we obtain 
%
\begin{align}
            \nonumber 2\iprod{u}{\nabla f(x^n)-\nabla f(x^m)} & \leq \tfrac{\tau}{2\lambda} \norm{u}^2 + \tfrac{2\lambda}{\tau} \norm{\nabla f(x^n)-\nabla f(x^m)}^2\\
            \label{C3} & \leq  \tfrac{\tau}{2\lambda}\norm{\Fnor(z^m)}^2 + \tfrac{1}{2\lambda^2} \norm{p}^2 + \tfrac{2\lambda \sL^2}{\tau} \norm{x^n-x^m}^2,
\end{align}
%
Summing up the estimates \cref{C1}--\cref{C3}, and noticing $\tau \leq \lambda$, it follows
%
\begin{align*}
        \norm{\Fnor(z^n)}^2  & \leq  ({1-\tfrac{\tau}{2\lambda}})\|{\Fnor(z^m)}\|^2 - \tfrac{2}{\lambda}\iprod{u}{x^n-x^m} \\
        & \hspace{4ex} + [(\sL+\lambda^{-1})^2 + {2\sL^2\lambda}{\tau^{-1}}] \norm{x^n-x^m}^2 + \tfrac{3}{2\lambda\tau} \norm{p}^2.
\end{align*}

\emph{Proof of (b).} By \ref{A1}--\ref{A2}, $\nabla f$ is $\sL$-continuous and $\vp$ is convex. Thus, we have
%
\begin{equation*}
        \psi(x^n)-\psi(x^m) \leq \iprod{\nabla f(x^m)}{x^n-x^m}+\tfrac{\sL}{2}\|x^n-x^m\|^2 + \tfrac{1}{\lambda}\iprod{z^n-x^n}{x^n-x^m},
\end{equation*}
%
where we used $\lambda^{-1}(z^n-x^n) \in\partial \vp(x^n)$ in the last inequality. Moreover, based on the definition of $\Fnor$, we can reformulate %\cref{eq:lem-1-est-1} 
the above inequality as
%
\begin{align*}
\psi(x^n)-\psi(x^m) & \leq \iprod{\nabla f(x^m)+\lambda^{-1}(z^m-x^m)}{x^n-x^m}+\tfrac{\sL}{2}\|{x^n-x^m}\|^2\\
& \hspace{4ex} + \lambda^{-1}\iprod{z^n-x^n}{x^n-x^m} - \lambda^{-1}\iprod{z^m-x^m}{x^n-x^m}\\
& \hspace{-4ex} = [{\tfrac{\sL}{2}-\tfrac{1}{\lambda}}]\|{x^n-x^m}\|^2 + 	\iprod{\Fnor(z^m)}{x^n-x^m} + \tfrac{1}{\lambda}\iprod{z^n-z^m}{x^n-x^m}.
\end{align*}
%
This concludes the proof by substituting \cref{eq:u-def1} into the last expression.
\end{proof}

\begin{proof}
Let $\omega\in\mathcal C$ be arbitrary and let $x^k = \sx^k(\omega)$,  $z^k = \sz^k(\omega)$, etc$.$ be the corresponding realizations. By the definition of the event $\mathcal C$, there exists $\revise{\{p_k\}_{k\in\N}}\subseteq\N$ such that \revise{$\{x^{p_k}\}_{k\in\N}$} is bounded and we have $\Fnor(z^k) \to 0$, $\psi(x^k) \to \psi^*$. Using the definition of the normal map, we can infer $\|z^{p_k}\| \leq \lambda(\|\Fnor(z^{p_k})\|+\|\nabla f(x^{p_k})\|)+\|x^{p_k}\|$. Hence, \revise{$\{z^{p_k}\}_{k\in\N}$} is also bounded and there is a convergent subsequence \revise{$\{z^{q_k}\}_{k\in\N}$} of \revise{$\{z^{p_k}\}_{k\in\N}$} such that $\lim_{k\to\infty} z^{q_k} = z^*$ for some $z^*$ satisfying $\|\Fnor(z^{*})\|=0$ and $x^*:=\proxl(z^*) \in \crit(\psi)$. Due to $\|x^k-x^*\| \leq \|z^k - z^*\|$, we then have $\lim_{k\to\infty} x^{q_k}=x^*$. Using the continuity of the Moreau envelope, this yields
%
\begin{align*} \psi^* & = {\lim}_{k \to \infty}\,\psi(x^{q_k})  = {\lim}_{k \to \infty}\,\vp(\proxi{\lambda}(z^{q_k})) + f(x^{q_k}) \\ & = {\lim}_{k\to\infty}\,\envi{\lambda}(z^{q_k}) - \tfrac{1}{2\lambda} \|z^{q_k}- x^{q_k}\|^2 + f(x^*) = \psi(x^*). \end{align*}
%
This readily implies $H(z^k) \to \psi^* = H(z^*)$ and finishes the proof.
\end{proof}

