\begin{theorem}
	\label{thm:iter converge}
	 Let \ref{A1}--\ref{A3}, \ref{B1}--\ref{B2}, and \ref{B4} hold and let $\revise{\{\sx^k\}_{k\in\N}}$ be generated by $\NSGD$ with step sizes $\revise{\{\alpha_k\}_{k\in\N}}\subset \R_{++}$ satisfying: %\vspace{-0.25ex}
     %
	\begin{equation}\label{eq:kl-step}  
		\lim_{k\to\infty}\alpha_k=0,\quad {\sum}_{k=0}^\infty \alpha_k = \infty \quad \text{and} \quad {\sum}_{k=0}^{\infty} \alpha_k^2 \sigma_k^2 \Big( {\sum}_{i=0}^k\alpha_i \Big)^{\mu}< \infty,% \quad \text{for some $\mu>\frac12$}.
        %\vspace{-0.25ex}
	\end{equation}
for some $\mu>1$. Then, we have $\sx^k \to \sx^*$ a$.$s$.$ for some $\sx^*:\Omega\to\crit(\psi)$.
\end{theorem}

\subsubsection{\texorpdfstring{Proof of \cref{thm:iter converge}}{Proof of Theorem 4.2}}

We start the proof by deriving certain summability results for the error terms $\su_k$ and $\sr_k$. %\\[1mm]

\noindent\textbf{Step 1:} \emph{Summability of error terms.} Due to condition \cref{eq:kl-step} (i.e., $\sum_{k=0}^\infty \alpha_k^2 \tau_{0,k}^{\mu}\sigma_k^2  <\infty$) and \cref{lem:err_estimate}, we have $\bar \sr:=\sum_{k=0}^\infty \tau_{0,t_k}^{\mu}\sr_k^2<\infty$ a$.$s$.$. This yields \vspace{-0.5ex}
\[
\sT\su_k = {10}\, {\sum}_{i=k}^\infty \sr_{i}^2 =  {10}\, {\sum}_{i=k}^\infty \tau_{0,t_i}^{-\mu} \tau_{0,t_i}^{\mu} \sr_{i}^2 \leq {10} \tau_{0,t_k}^{-\mu} \cdot {\sum}_{i=k}^\infty  \tau_{0,t_i}^{\mu} \sr_{i}^2 \leq {10\bar \sr}  \cdot \tau_{0,t_k}^{-\mu}.
\]
%
Using $\delta \sT \leq \tau_{t_k,t_{k+1}}$, it follows $\tau_{0,t_k} \geq  \tau_{0,t_0} + \delta \sT k$ and $\su_k\to 0$ a$.$s$.$, which implies 
%
\begin{equation}
    \label{eq:summability u_k}
    {\sum}_{k=0}^\infty \su_k^\theta \leq (10\bar\sr/\sT)^\theta  \cdot {\sum}_{k=0}^\infty (\tau_{0,t_0} + \delta \sT k)^{-\mu\theta}<\infty \quad \text{for all}\quad \theta > \tfrac{1}{\mu}.
\end{equation}
%
Hence, we have $\sum_{k=j}^\infty \su_k^\theta \to 0$ as $j\to\infty$ for all $\theta > {\mu}^{-1}$. Moreover, it holds that \vspace{-1ex}
%
\begin{equation}\label{eq:rk-sum}
{\sum}_{k=0}^\infty \sr_k = {\sum}_{k=0}^\infty \tau_{0,t_k}^{-\frac{\mu}{2}}\cdot \tau_{0,t_k}^{\frac{\mu}{2}} \sr_k \leq \Big({ \bar{\sr} \cdot {\sum}_{k=0}^\infty (\tau_{0,t_0} + \delta \sT  k)^{-\mu} }\Big)^{1/2} < \infty \quad \text{a$.$s$.$.}
\end{equation}
%
Let us fix $\theta\in(\max\{\frac{1}{\mu},\frac12\},1)$ and let us introduce the events $\mathcal E := \{\omega : \sum_{k=0}^\infty \su_k(\omega)^\theta < \infty, \, \sum_{k=0}^\infty \sr_k(\omega) < \infty\}$ and $\mathcal C := \mathcal X \cap \{\omega : \Fnor(\sz^k(\omega)) \to 0, \, \psi(\sx^k(\omega))\to\spsi^*(\omega)\}$. Condition \cref{eq:kl-step} implies that \ref{B3} is satisfied. Thus, by \cref{thm:global_convergence-2}, \cref{eq:summability u_k}, \cref{eq:rk-sum}, and \ref{B4}, we can infer $\Prob(\mathcal C) = \Prob(\mathcal E) = \Prob(\mathcal D)=1$, where $\mathcal D = \mathcal C \cap \mathcal E$. %\\[1mm]

\noindent\textbf{Step 2:} \emph{Subsequence convergence and roadmap.} We first present an auxiliary result.

\begin{lemma}[Subsequence convergence]\label{lem:subsequence converge}
Let \ref{A1}--\ref{A2} and \ref{B1}--\ref{B4} hold and let $\omega\in\mathcal C$ be arbitrary. Then, there exist $z^*\in\Rn$ and a subsequence $\revise{\{q_k\}_{k\in\N}}\subseteq \N$ such that $x^*:=\proxl(z^*)\in\crit(\psi)$, $x^{q_k} \to x^*$, $z^{q_k} \to z^*$, $\psi(x^k) \to \psi(x^*) = \psi^*$, and $\mer(z^{k}) \to \mer(z^*) = \psi^*$ as $k\to\infty$, where  
$\revise{\{x^k\}_{k\in\N}} = \revise{\{\sx^k(\omega)\}_{k\in\N}}$ and $\revise{\{z^k\}_{k\in\N}}= \revise{\{\sz^k(\omega)\}_{k\in\N}}$. 
\end{lemma}

The proof of \cref{lem:subsequence converge} can be found in \cref{proof:lem:subsequence converge}. To simplify the notation, we set
%
$\sd_k := {\max}_{t_k<i\leq t_{k+1}} \max\{\|\sx^i-\sx^{t_k}\|,\|\sz^i-\sz^{t_k}\|\}$.

\cref{lem:est-err} and $\tau_{t_k,t_{k+1}} \leq \sT$ then imply 
%
\begin{equation}\label{dk-bound}
    % \sd_k^2 \leq 4 \sT^2 \|\Fnor(\sz^{t_k})\|^2 + 4 \sr_k^2.
    \sd_k \leq 2 \sT \|\Fnor(\sz^{t_k})\| + 2 \sr_k.
\end{equation}
%
Our goal is to show $\sx^k \to \sx^*$ a$.$s$.$. Thanks to $\Prob(\mathcal D)=1$, it suffices to prove that $\revise{\{\sx^k(\omega)\}_{k\in\N}}$ is a Cauchy sequence for all $\omega \in \mathcal D$. Let $\omega \in \mathcal D$ be arbitrary and let $\revise{\{x^k\}_{k\in\N}} = \revise{\{\sx^k(\omega)\}_{k\in\N}}$,  $\revise{\{z^k\}_{k\in\N}} = \revise{\{\sz^k(\omega)\}_{k\in\N}}$, $\revise{\{r_k\}_{k\in\N}} = \revise{\{\sr_k(\omega)\}_{k\in\N}}$, etc. denote the corresponding realizations. For given $\varepsilon>0$, we need to show that there is $k$ such that $\|x^m - x^n\|<\varepsilon$ for all $k\leq m<n$. 

We claim that it suffices to establish ${\sum}_{k=0}^{\infty}\,d_k< \infty$. In this case, there is $k^\prime\in\N$ such that ${\sum}_{j=k}^{\infty}\,d_j<\varepsilon/2$ for all $k \geq k^\prime$. For any $n > m > t_{k^\prime}$, we have $k^\prime \leq \fk(m)\leq \fk(n)$. Therefore, using the triangle inequality and the above bound, we obtain %\vspace{-1.5ex}
%
\begin{equation*}
\|x^m - x^n\| \leq d_{\fk(m)} + d_{\fk(n)} + {\sum}_{j=\fk(m)}^{{\fk(n)-1}}\|x^{t_{j+1}}-x^{t_j}\| \leq 2 {\sum}_{j=\fk(m)}^{{\fk(n)}} d_j< \varepsilon, 
\end{equation*}
%
which proves our claim. In the remaining steps, we establish summability of $\revise{\{d_k\}_{k\in\N}}$.%\\[1mm]

\noindent\textbf{Step 3:} \emph{Entering the local region and a KL-based bound for $\revise{\{d_k\}_{k\in\N}}$.} By \cref{lem:subsequence converge}, there exists a subsequence $\revise{\{q_k\}_{k\in\N}}$ such that $x^{q_k} \to x^*$, $z^{q_k} \to z^*$ for some $z^*$ with $x^* = \proxl(z^*) \in\crit(\psi)$, and $\mer(z^{k}) \to \mer(z^*) = \psi^*$. Based on the definition of $\fk$ and $d_k$, it holds that $\max\{\|x^{q_k} - x^{t_{\fk(q_k)}}\|,\|z^{q_k} - z^{t_{\fk(q_k)}}\|\} \leq d_{\fk(q_k)}$. Due to $\|\Fnor(z^{t_{{\fk(q_k)}}})\|\to0$, $r_{{\fk(q_k)}}\to0$, and \cref{dk-bound}, we then have $d_{{\fk(q_k)}} \to 0$, $x^{t_{\fk(q_k)}} \to x^*$, and $z^{t_{\fk(q_k)}} \to z^*$.


Applying \cref{lem:KL-mer}, there exist $\rho>0$, $\eta\in(0,1]$, and a concave function $\varrho:[0,\eta)\to\R_+$, $\varrho \in C^1((0,\eta))$ (satisfying properties (a)--(b) in \cref{lem:KL-mer}) such that
%
\begin{equation}
         \label{eq:super-proof-kl}
         \varrho^\prime(|\mer(z)-\psi^*|) \cdot  \|\Fnor(z)\|\geq 1\quad %\text{holds}
\end{equation}
%
for all $z\in\cB_\rho(z^*) \cap\{z \in \Rn:0<|\mer(z)-\psi^*| + \frac{\xi\lambda}{2}\|\Fnor(z)\|^2<\eta\}$.

Next, we define $\Delta_k:= \varrho(\mer(z^{t_k}) -\psi^* + u_k)$.
Since \revise{$\{\mer(z^{t_k}) -\psi^* + u_k\}_{k \in \N}$} is monotonically decreasing (see \cref{eq:strong-0}) with $\mer(z^{t_k}) + u_k \to \psi^*$, $\Delta_k$ is well-defined. By $\omega \in \mathcal D$, $\varrho(0) = 0$, and by the previous discussion, there then is $\hat k \in \N$ such that
%
\begin{subequations}
\label{eq:choose rho eta}
    \begin{align}
        \label{eq:choose rho eta-1} &\|z^{t_{\hat k}} - z^*\| + 20\xi^{-1}\Delta_{\hat{k}}  + 2\varsigma\sT {\sum}_{i=\hat k}^\infty\, u_i^\theta + 2{\sum}_{i=\hat k}^\infty\, r_i< \rho \quad \text{and} \quad \\ \label{eq:choose rho eta-2} &|\mer(z^{t_k})-\psi^*| + \max\{\tfrac{\xi\lambda}{2}\|\Fnor(z^{t_k})\|^2, u_k\} \leq  \eta\quad\text{for all} \quad k \geq \hat k. 
    \end{align}
\end{subequations}

Let $k \geq \hat k$ be now given with $z^{t_k} \in \mathcal B_\rho(z^*)$. (In particular, this is true for $k = \hat k$). Hence, by \cref{eq:choose rho eta-2}, the KL inequality \cref{eq:super-proof-kl} is applicable and we have
%
\begin{subequations}
    \begin{align}
	\label{eq:long-equation-1}\Delta_k - \Delta_{k+1}
    & \geq \varrho^\prime(\mer(z^{t_k}) - \psi^*+u_k)(\mer(z^{t_k}) +u_k - [\mer(z^{t_{k+1}})+u_{k+1}]) \\
	\label{eq:long-equation-2}& \geq \varrho^\prime(|\mer(z^{t_k}) - \psi^*|+u_k) (\xi \sT \|\Fnor(z^{t_k})\|^2/10) \\%[1mm]
	\label{eq:long-equation-3}&\geq (1/\varrho^\prime({|\mer(z^{t_k}) - \psi^*|})  + \varsigma u_k^\theta)^{-1} (\xi \sT \|\Fnor(z^{t_k})\|^2/10) \\
    \label{eq:long-equation-4}&\geq \frac{\xi\sT}{10}\cdot \frac{\|\Fnor(z^{t_k})\|^2}{\|\Fnor(z^{t_k})\| +  \varsigma u_k^\theta}\geq \frac{\xi \sT}{10}\srt{\|\Fnor(z^{t_k})\| -  \varsigma 
 u_k^\theta}.
\end{align}
\end{subequations}
%
The inequality \cref{eq:long-equation-1} is due to the concavity of $\varrho$, \cref{eq:long-equation-2} follows from the descent-type property \cref{eq:strong-0} and the fact that $\varrho^\prime$ is non-increasing, \cref{eq:long-equation-3} utilizes $\varrho^\prime(s+t) \geq [1/\varrho^\prime(s) + \varsigma t^{\theta}]^{-1}$ (see \cref{lem:KL-mer} (a)), and \cref{eq:long-equation-4} is based on \cref{eq:super-proof-kl} and ${a^2}\geq a^2-b^2$, $a,b\in \R$. Rearranging yields $\sT\|\Fnor(z^{t_k})\| \leq 10\xi^{-1}(\Delta_k - \Delta_{k+1}) + \varsigma \sT u_k^\theta$. Combining this estimate with $d_k \leq 2 \sT \|\Fnor(z^{t_k})\| + 2 r_k$ (see \cref{dk-bound}), we can infer
%
\begin{equation}
    \label{eq:d bound}
d_k \leq 20\xi^{-1}(\Delta_k - \Delta_{k+1}) + 2\varsigma\sT u_k^\theta + 2r_k.
\end{equation}

\noindent\textbf{Step 4:} \emph{Attracted by the local region.}  We now show that the following statements hold for all $k \geq \hat k$: 
%
	\begin{enumerate}[label=(\alph*),topsep=4pt,itemsep=0.5ex,partopsep=0ex]
	\item $z^{t_k} \in \mathcal{B}_{\rho}(z^*)$ and $|\mer(z^{t_k}) - \psi^*| + \max\{\frac{\xi\lambda}{2}\|\Fnor(z^{t_k})\|^2,u_k\}< \eta$.
 %\vspace{1mm}
	\item $\sum_{i=\hat k}^{k}d_i  \leq 20\xi^{-1}[\Delta_{\hat k} - \Delta_{k+1}] + 2\varsigma\sT \sum_{i=\hat k}^k u_i^\theta + 2\sum_{i=\hat k}^k r_i.$
	\end{enumerate}
% 
We will prove these statements by induction. First, (a) and (b) are satisfied for $k=\hat k$ thanks to \cref{eq:choose rho eta} and \cref{eq:d bound}. To conduct the induction step, let us assume that (a)--(b) hold for some $k =n \geq \hat k$. We first verify (a) for $k=n+1$. Due to \cref{eq:choose rho eta-2}, the bound $|\mer(z^{t_{n+1}}) - \psi^*| + \max\{\frac{\xi\lambda}{2}\|\Fnor(z^{t_{n+1}})\|^2,u_{n+1}\} < \eta$ is immediate. Moreover, we have
%
\begin{align*}
    \|z^{t_{n+1}} - z^*\| &\leq \|z^{t_{\hat k}} - z^*\| + {\sum}_{i=\hat{k}}^n \|z^{t_{i+1}} - z^{t_{i}}\| \leq  \|z^{t_{\hat k}} - z^*\| + {\sum}_{i=\hat k}^n \,d_i\\
    &\leq \|z^{t_{\hat k}} - z^*\| +  20\xi^{-1}[\Delta_{\hat k} - \Delta_{n+1}] + 2\varsigma\sT {\sum}_{i=\hat k}^\infty\, u_i^\theta + 2{\sum}_{i=\hat k}^\infty\, r_i < \rho,
\end{align*}
%
where the second inequality follows from the definition of $d_k$, the third step uses (b) for $k=n$, and the last step holds due to \cref{eq:choose rho eta-1} and $\Delta_{n+1}\geq 0$. Next, we prove that (b) holds for $k=n+1$. Invoking \cref{eq:d bound} with $k=n+1$ and (b) with $k=n$, we obtain
%
\[
{\sum}_{i=\hat k}^{n+1}\,d_i = d_{n+1} + {\sum}_{i=\hat k}^{n}\,d_i \leq 20\xi^{-1}[\Delta_{\hat k} - \Delta_{n+2}] + 2\varsigma\sT {\sum}_{i=\hat k}^{n+1}\, u_i^\theta + 2{\sum}_{i=\hat k}^{n+1}\, r_i.
\]
%
This completes the induction. Thus, (a), (b), and \cref{eq:d bound} hold for all $k \geq \hat k$. %\\[1mm]

\noindent\textbf{Step 5:} \emph{Summability of $\revise{\{d_k\}_{k\in\N}}$.} Taking $k\to\infty$ in \textbf{Step 4} (b) and due to $\Delta_k \geq 0$, we have \vspace{-1.5ex}
%
\begin{equation*} 
{\sum}_{i=\hat k}^{\infty}d_i  \leq 20\xi^{-1}\Delta_{\hat k} + 2\varsigma\sT {\sum}_{i=\hat k}^{\infty} u_i^\theta + 2{\sum}_{i=\hat k}^{\infty} r_i < \rho < \infty.
\end{equation*}
%
This yields $\sum_{k=0}^{\infty}d_k < \infty$ and, following \textbf{Step 2}, this completes the proof. \hfill \proofbox

\be\label{eq:update-short}
    \sz^{k+1} = \sz^k - \alpha_k(\sg^k + \lambda^{-1}(\sz^k-\sx^k)) \quad \text{and} \quad \sx^{k+1} = \proxl(\sz^{k+1}),
\ee

We first present several basic estimates and properties that facilitate the analysis of $\NSGD$. Since $\vp$ is assumed to be convex, lsc., and proper (cf$.$ \ref{A1}), the proximity operator $\proxl$ is firmly nonexpansive, \cite{mor65,baucom11}. Hence, recalling $\sx^k = \proxl(\sz^k)$, it holds that
%
\begin{equation}\label{prox-prop}
    \|\sx^n-\sx^m\|^2 \leq \iprod{\sz^n-\sz^m}{\sx^n-\sx^m}\leq \norm{\sz^n-\sz^m}^2 \quad \forall~\revise{m<n} \quad \text{(a$.$s$.$)}.
\end{equation}

\begin{align}
    \nonumber \sz^n&=\sz^{n-1} -\alpha_{n-1}[\sg^{n-1}+ \tfrac{1}{\lambda}(\sz^{n-1} - \sx^{n-1})] =\sz^{n-1} - \alpha_{n-1}[\Fnor(\sz^{n-1}) +\se^{n-1}]	\\
     \nonumber &=\sz^m - {\sum}_{i=m}^{n-1}\alpha_i\Fnor(\sz^i) - {\sum}_{i=m}^{n-1} \alpha_i\se^i \\
    \nonumber &=\sz^m - {{\sum}_{i=m}^{n-1}\alpha_i}\Fnor(\sz^m) - {\sum}_{i=m}^{n-1} \alpha_i[\Fnor(\sz^i)-\Fnor(\sz^m)] - {\sum}_{i=m}^{n-1} \alpha_i\se^i \\ & = \sz^m - \tau_{m,n} \Fnor(\sz^m) + \scp^{m,n} \revise{\quad \forall~m<n,}\label{eq:pretty-important}
\end{align}

\begin{align}
         \su^{m,n}  & :=  \lambda^{-1}(\sz^n-\sz^m) + \Fnor(\sz^m) \label{eq:u-def1}\\  &\;=  (\lambda^{-1}-\tau_{m,n}^{-1})(\sz^n-\sz^m) + \tau_{m,n}^{-1} \scp^{m,n} \label{eq:u-def2}\\
          &\;=  (1-\lambda^{-1}\tau_{m,n}) \Fnor(\sz^m) + \lambda^{-1}\scp^{m,n}, \quad \revise{m < n}.\label{eq:u-def3}
     \end{align}

\begin{definition}[Merit function]\label{def:mer-fun} Given $\lambda > 0$, we define the merit function: 
 \[\mer(z):=\psi(\prox{\lambda\vp}(z)) + \frac{\xi\lambda}{2}\|\Fnor(z)\|^2,\quad \text{where} \quad \xi:={(2+2\lambda^2 \sL^2)^{-1}}.\]
\end{definition}

\begin{definition}[Time indices]\label{def:time win}
Let $\sT>0$ and $\delta\in(0,1)$ be given. We introduce the mapping $\varpi:\N \to \N\cup \{\pm\infty\}$, $\varpi(k):=\sup\{n > k: \tau_{k,n} \leq \sT\}$, where $\tau_{m,n} = {\sum}_{k=m}^{n-1} \alpha_k$. The \emph{time indices} $\revise{\{t_k\}_{k\in\N}}$, associated with the \emph{time window} $\sT$ \revise{(and the step sizes $\{\alpha_k\}_{k \in \N}$)}, are defined as 
\[
t_0 := \inf\{i: \alpha_j \leq (1-\delta)\sT \text{ for all $j\geq i$}\}\quad \text{and} \quad t_{k+1} := \varpi(t_k).
\]
\end{definition}

\begin{equation}\label{index-def}
\fk(i) = \max\{k: t_k < i\}\quad \text{for all $i>t_0$}.
\end{equation}

\begin{equation}
    \label{eq:def delta and T}
    \sr_k := \scs_{t_{k},t_{k+1}}, \;\; \delta := \frac45, \;\;  \sT := \frac{\sqrt{\xi}}{8\Llambda},\quad \text{where} \quad \Llambda =\sL+\frac{2}{\lambda}, \;\; \xi =\frac{1}{2+2\lambda^2 \sL^2}.
\end{equation}

\begin{enumerate}[label=\textup{\textrm{(H.3)}},leftmargin=3em,topsep=2mm,itemsep=1ex,partopsep=0ex]
        \item \label{A3} The objective function $\psi : \Rn \to \Rex$ is definable. %\vspace{2mm}
\end{enumerate}

Clearly, if $\omega\in\cX$, then the realization $\revise{\{x^k\}_{k\in\N}} = \revise{\{\sx^k(\omega)\}_{k\in\N}}$ has at least one bounded subsequence and accumulation point. We will work with the following assumption: 
%\vspace{1.5mm}
 \begin{enumerate}[label=\textup{\textrm{(S.4)}},leftmargin=3em,topsep=1.5mm,itemsep=1ex,partopsep=0ex]
        \item \label{B4} The event $\cX \in \mathcal F$ occurs with probability $1$, i.e., $\Prob(\cX)=1$.
    \end{enumerate}

\begin{lemma}[Iterate bounds]
    \label{lem:est-err}
     Let \ref{A1}--\ref{A2} and \ref{B1}--\ref{B2} hold and let $\revise{\{\sx^k\}_{k\in\N}}$ and $\revise{\{\sz^k\}_{k\in\N}}$ be generated by $\NSGD$. Let us set $\Llambda := \sL+2\lambda^{-1}$. For all $0\leq m<n$ with $\tau_{m,n} \leq 1/(2\Llambda)$, we have
     %
    \begin{align*}
        \max_{m<i\leq n}\|\sx^i-\sx^m\| &\leq \max_{m<i\leq n}\|\sz^i-\sz^m\| \leq 2\tau_{m,n} \norm{\Fnor(\sz^m)} + 2\scs_{m,n}\quad \text{and}\\
        \|{\scp^{m,n}}\| &\leq 2\Llambda\tau_{m,n}^2\norm{\Fnor(\sz^m)} + 2\scs_{m,n}. 
    \end{align*}
\end{lemma}

\begin{proof} Let $\omega \in \Omega$ be arbitrary and let us set $\tau = \tau_{m,n}$, $p = p^{m,n} = \scp^{m,n}(\omega)$, $s = s_{m,n} = \scs_{m,n}(\omega)$, $x^k = \sx^k(\omega)$, $z^k = \sz^k(\omega)$, etc. It follows from the definition of $p^{m,i}$ \revise{and $s_{m,n}$} and the triangle inequality that
%
\begin{align}
        \nonumber \|p^{m,i}\| &\leq {\sum}_{j=m}^{i-1}\alpha_j\|{\Fnor(z^j) - \Fnor(z^m)}\| + \Big\|{{\sum}_{j=m}^{i-1} \alpha_j e^j}\Big\| \\ &\leq {\sum}_{j=m}^{i-1}\alpha_j\|{\Fnor(z^j) - \Fnor(z^m)}\| + s,\qquad \text{for all $i\in(m,n] \cap \N$.} \label{eq:lem-4-est-1}
\end{align}
% 
Recalling $\Fnor(z) = \nabla f(x) + \lambda^{-1}(z-x)$ and using \ref{A1} and the nonexpansiveness of the proximity operator (i.e., $\|x^i-x^m\| \leq \|z^i-z^m\|$), we have
%
\begin{equation}
\label{eq:nor is Lip}
     \|\Fnor(z^j) - \Fnor(z^m)\| \leq (\sL+\lambda^{-1})\|x^j-x^m\| + \lambda^{-1}\|z^j-z^m\| \leq  \Llambda \|z^j-z^m\|,% =: C_\lambda\|z^i-z^m\|.
\end{equation} 
%
where $\Llambda =\sL+2\lambda^{-1}$. Thus, combining the relation $z^i = z^m - \tau_{m,i}\Fnor(z^m) + p^{m,i}$ (cf$.$ \cref{eq:pretty-important})\revise{, $\tau_{m,i} \leq \tau$,} and the inequality \cref{eq:lem-4-est-1}, we can infer
% 
\begin{align}
    \nonumber \|z^i-z^m\| &\leq \tau_{m,i} \|\Fnor(z^m)\| + \|p^{m,i}\| \\
    \nonumber &\leq {\sum}_{j=m}^{i-1} \alpha_j \|\Fnor(z^j)-\Fnor(z^m)\| + \tau \|\Fnor(z^m)\| + s\\ 
    \label{eq:lem-4-est-3} &\leq \Llambda {\sum}_{j=m}^{i-1} \alpha_j  \|z^j-z^m\| + \tau \|\Fnor(z^m)\| + s, \qquad \text{for all $i\in(m,n] \cap \N$}.
\end{align}
%
We now apply Gronwall's inequality (\cref{Thm:G}) upon setting $b_1 :=\tau \|\Fnor(z^m)\| + s$, $b_2 := \Llambda$, $a_k:=\alpha_{m+k}$, $y_k:=\|z^{m+k} - z^m\|$, and $t:=i-m-1$. For all $i\in(m,n] \cap \N$, this establishes the following upper bound  
%
\begin{equation}
            \|z^i - z^m\|  \leq \exp(\tau \Llambda) \cdot [\tau\|\Fnor(z^m)\|+s]\leq 2\tau\|\Fnor(z^m)\| + 2s,
            \label{eq:lem-4-est-5}
\end{equation}
%
where the last inequality is due to $\tau\Llambda \leq \frac12$ and $\exp(\frac12)\leq 2$. Moreover, it follows from $\|x^i-x^m\| \leq \|z^i-z^m\|$ that ${\max}_{m<i\leq n}\|x^i-x^m\| \leq {\max}_{m<i\leq n}\|z^i-z^m\| \leq 2\tau\|\Fnor(z^m)\| + 2s$. This verifies the first bound in \cref{lem:est-err}. 

Next, combining \cref{eq:nor is Lip} and \cref{eq:lem-4-est-5}, we obtain
%
\[
{\max}_{m<i\leq n} \|\Fnor(z^i) - \Fnor(z^m)\|\leq \Llambda{\max}_{m<i\leq n}\|z^i-z^m\| \leq 2\Llambda[\tau\|\Fnor(z^m)\| + s].
\]
%
Using this bound in \cref{eq:lem-4-est-1} with $i=n$ and recalling $\tau={\sum}_{i=m}^{n-1} \alpha_i$, this yields $\|p\|\leq s+ 2\Llambda (\tau\|\Fnor(z^m)\| + s) {\sum}_{j=m}^{n-1} \alpha_j \leq 2\Llambda\tau^2\|\Fnor(z^m)\| + 2s$.
\end{proof}

\begin{proof} Let $\omega \in \Omega$ be arbitrary and let us set $\tau = \tau_{m,n}$, $p = p^{m,n} = \scp^{m,n}(\omega)$, $s = s_{m,n} = \scs_{m,n}(\omega)$, $x^k = \sx^k(\omega)$, $z^k = \sz^k(\omega)$, etc. It follows from the definition of $p^{m,i}$ \revise{and $s_{m,n}$} and the triangle inequality that
%
\begin{align}
        \nonumber \|p^{m,i}\| &\leq {\sum}_{j=m}^{i-1}\alpha_j\|{\Fnor(z^j) - \Fnor(z^m)}\| + \Big\|{{\sum}_{j=m}^{i-1} \alpha_j e^j}\Big\| \\ &\leq {\sum}_{j=m}^{i-1}\alpha_j\|{\Fnor(z^j) - \Fnor(z^m)}\| + s,\qquad \text{for all $i\in(m,n] \cap \N$.} \label{eq:lem-4-est-1}
\end{align}

Recalling $\Fnor(z) = \nabla f(x) + \lambda^{-1}(z-x)$ and using \ref{A1} and the nonexpansiveness of the proximity operator (i.e., $\|x^i-x^m\| \leq \|z^i-z^m\|$), we have
%
\begin{equation}
\label{eq:nor is Lip}
     \|\Fnor(z^j) - \Fnor(z^m)\| \leq (\sL+\lambda^{-1})\|x^j-x^m\| + \lambda^{-1}\|z^j-z^m\| \leq  \Llambda \|z^j-z^m\|,% =: C_\lambda\|z^i-z^m\|.
\end{equation} 
%
where $\Llambda =\sL+2\lambda^{-1}$. Thus, combining the relation $z^i = z^m - \tau_{m,i}\Fnor(z^m) + p^{m,i}$ (cf$.$ \cref{eq:pretty-important})\revise{, $\tau_{m,i} \leq \tau$,} and the inequality \cref{eq:lem-4-est-1}, we can infer
% 
\begin{align}
    \nonumber \|z^i-z^m\| &\leq \tau_{m,i} \|\Fnor(z^m)\| + \|p^{m,i}\| \\
    \nonumber &\leq {\sum}_{j=m}^{i-1} \alpha_j \|\Fnor(z^j)-\Fnor(z^m)\| + \tau \|\Fnor(z^m)\| + s\\ 
    \label{eq:lem-4-est-3} &\leq \Llambda {\sum}_{j=m}^{i-1} \alpha_j  \|z^j-z^m\| + \tau \|\Fnor(z^m)\| + s, \qquad \text{for all $i\in(m,n] \cap \N$}.
\end{align}

We now apply Gronwall's inequality (\cref{Thm:G}) upon setting $b_1 :=\tau \|\Fnor(z^m)\| + s$, $b_2 := \Llambda$, $a_k:=\alpha_{m+k}$, $y_k:=\|z^{m+k} - z^m\|$, and $t:=i-m-1$. For all $i\in(m,n] \cap \N$, this establishes the following upper bound  
%
\begin{equation}
            \|z^i - z^m\|  \leq \exp(\tau \Llambda) \cdot [\tau\|\Fnor(z^m)\|+s]\leq 2\tau\|\Fnor(z^m)\| + 2s,
            \label{eq:lem-4-est-5}
\end{equation}
%
where the last inequality is due to $\tau\Llambda \leq \frac12$ and $\exp(\frac12)\leq 2$. Moreover, it follows from $\|x^i-x^m\| \leq \|z^i-z^m\|$ that ${\max}_{m<i\leq n}\|x^i-x^m\| \leq {\max}_{m<i\leq n}\|z^i-z^m\| \leq 2\tau\|\Fnor(z^m)\| + 2s$. This verifies the first bound in \cref{lem:est-err}.

\begin{lemma}
    \label{lem:err_estimate}
    Let \ref{B1}--\ref{B2} hold and let $\revise{\{\alpha_k\}_{k\in\N}}$ be given. Then for any (arbitrary) subsequence $\revise{\{t_k\}_{k\in\N}} \subseteq \N$, we have $\Exp[{{\scs_{t_k,t_{k+1}}^2}}] \leq 4 \sum_{i=t_k}^{t_{k+1}-1}\alpha_i^2\sigma_i^2$. Moreover, if there is a non-decreasing sequence $\revise{\{\beta_k\}_{k\in\N}}\subset\R_{++}$ such that ${\sum}_{k=0}^\infty \alpha_k^2\beta_k^2\sigma_k^2 < \infty$, it holds that
    %
    \[ {\sum}_{k=0}^\infty \beta_{t_k}^2 \Exp[{{\scs_{t_k,t_{k+1}}^2}}] < \infty \quad \text{and}\quad {\sum}_{k=0}^\infty \beta_{t_k}^2 \scs_{t_k,t_{k+1}}^2 < \infty \quad \text{a$.$s$.$.}\] 
    %
\end{lemma}

(Similarly for $\ell \geq t_{k+1}-t_k$). Hence, \revise{$\{\sy^\ell\}_{\ell\in\N}$} defines a \revise{$\{\mathcal{U}_{\ell}\}_{\ell\in\N}$}-martingale. Let us further set $\sr_k = \scs_{t_k,t_{k+1}}$. By the Burkholder-Davis-Gundy inequality (\cref{Thm:BDG} with $p=2$ and $C_p\leq 4$) and assumption \ref{B1}, we have $\Exp[{\sr_k^2}] =\Exp[{{\sup}_{\ell>0} \|\sy^\ell\|^2}]$ and
%
\begin{align*} 
\nonumber\Exp[{\sr_k^2}] \leq 4 \Exp\Big[{ {\sum}_{\ell=1}^{\infty}\|\sy^\ell-\sy^{\ell-1}\|^2}\Big] & = 4 {\sum}_{i=t_k}^{t_{k+1}-1}\alpha_i^2 \Exp[{ \|\se^i\|^2}]  \leq 4 {\sum}_{i=t_k}^{t_{k+1}-1} \alpha_i^2\sigma_i^2. 
\end{align*}

This proves the first claim in \Cref{lem:err_estimate}. Since $\revise{\{\beta_k\}_{k\in\N}}$ is non-decreasing, we obtain%
%
\begin{equation}\label{eq:app-bdg}
	\beta_{t_k}^2 \Exp[\sr_k^2] \leq 4 \beta_{t_k}^2 {\sum}_{i=t_k}^{t_{k+1}-1} \alpha_i^2\sigma_i^2 \leq 4  {\sum}_{i=t_k}^{t_{k+1}-1} \alpha_i^2\beta_{i}^2\sigma_i^2
\end{equation}

for all $k \in \N$. The monotone convergence theorem and \cref{eq:app-bdg} further imply
%
\begin{align*}
 \Exp\Big[{ {\sum}_{k=0}^\infty \beta_{t_k}^2{\sr_k^2}}\Big] = {\sum}_{k=0}^{\infty}\beta_{t_k}^2 \Exp[\sr_k^2] 
 \leq 
    {4} {\sum}_{i=t_{0}}^\infty \alpha_i^2\beta_i^2\sigma_i^2 < \infty,
\end{align*}
%
and consequently, it holds that $\sum_{k=0}^\infty \beta_{t_k}^2{\sr_k^2} < \infty$ a$.$s$.$.
\end{proof}

\begin{lemma}
	\label{lem:basic bounds}
	Let the assumptions \ref{A1}--\ref{A2} and \ref{B1}--\ref{B2} be satisfied and let the sequences $\revise{\{\sx^k\}_{k\in\N}}$, $\revise{\{\sz^k\}_{k\in\N}}$ be generated by $\NSGD$. Let $0 \leq m<n$ be given with $\tau_{m,n} < \lambda$. Then, the following two bounds are valid:
    \begin{enumerate}[label=\textup{\textrm{(\alph*)}},leftmargin=3em,topsep=2pt,itemsep=.5ex,partopsep=0ex]
    \item It holds that $\norm{\Fnor(\sz^n)}^2 \leq  ({1-\frac{\tau_{m,n}}{2\lambda}})\norm{\Fnor(\sz^m)}^2 - \frac{2}{\lambda}\iprod{\su^{m,n}}{\sx^n-\sx^m} + [({\sL+\frac{1}{\lambda}})^2 + \frac{2\lambda \sL^2}{\tau_{m,n}}] \norm{\sx^n-\sx^m}^2 + \frac{3}{2\lambda\tau_{m,n}} \norm{\scp^{m,n}}^2$.
    \item We have $\psi(\sx^n) \leq \psi(\sx^m) + ({\frac{\sL}{2}-\frac{1}{\lambda}})\norm{\sx^n-\sx^m}^2 + \iprod{\su^{m,n}}{\sx^n-\sx^m}.$	
    \end{enumerate}
\end{lemma}

\begin{proof}[Proof of (a)]
Let $\omega\in\Omega$ be arbitrary and denote $x^k = \sx^k(\omega)$, $z^k = \sz^k(\omega)$, $p = \scp^{m,n}(\omega)$, $u = \su^{m,n}(\omega)$, $\tau = \tau_{m,n}$, etc$.$. Recalling $\Fnor(z) = \nabla f(x) + \lambda^{-1}(z-x)$ and by the definition \cref{eq:u-def1} of $\su^{m,n}$, we can express $\Fnor(z^n)$ as
%
\begin{align*} 
    \Fnor(z^n) 
    & = \Fnor(z^m) + [\nabla f(x^n)-\nabla f(x^m)] + \lambda^{-1}\prt{z^n-z^m+x^m-x^n}\\
    & = u + [\nabla f(x^n)-\nabla f(x^m)] - \lambda^{-1}(x^n-x^m).
\end{align*}	
%
Taking squares and using the Lipschitz continuity of $\nabla f$, this yields
%
\begin{align}
            \nonumber \norm{\Fnor(z^n)}^2 & = \norm{u}^2 + 2\iprod{u}{(\nabla f(x^n)-\nabla f(x^m)) - \lambda^{-1}(x^n-x^m)} \\
            \nonumber&\hspace{4ex}  +  \norm{(\nabla f(x^n)-\nabla f(x^m)) - \lambda^{-1}(x^n-x^m)}^2\\
            \label{C1} & \hspace{-6ex} \leq \norm{u}^2 + 2\iprod{u}{(\nabla f(x^n)-\nabla f(x^m))-\lambda^{-1}(x^n-x^m)} + (\sL+{\lambda}^{-1})^2 \norm{x^n-x^m}^2.
\end{align}
%
Using $u=(1-\lambda^{-1}\tau)\Fnor(z^m) + \lambda^{-1}p$ (cf$.$ \cref{eq:u-def3}) and $\norm{a+b}^2 \leq (1+\varepsilon) \norm{a}^2 + (1+\frac{1}{\varepsilon})\norm{b}^2$ with $a= (1-\lambda^{-1}\tau) \Fnor(z^m)$, $b = \lambda^{-1}p$, and $\varepsilon = \frac{\lambda^{-1}\tau}{1-\lambda^{-1}\tau}$, we have
%
\begin{equation}\label{C2}
        \norm{u}^2 \leq (1-\lambda^{-1}{\tau}) \|{\Fnor(z^m)}\|^2 + (\lambda\tau)^{-1} \|{p}\|^2.
\end{equation}
%
Utilizing Young's inequality for $2\iprod{u}{\nabla f(x^n)-\nabla f(x^m)}$ and \cref{C2}, we obtain 
%
\begin{align}
            \nonumber 2\iprod{u}{\nabla f(x^n)-\nabla f(x^m)} & \leq \tfrac{\tau}{2\lambda} \norm{u}^2 + \tfrac{2\lambda}{\tau} \norm{\nabla f(x^n)-\nabla f(x^m)}^2\\
            \label{C3} & \leq  \tfrac{\tau}{2\lambda}\norm{\Fnor(z^m)}^2 + \tfrac{1}{2\lambda^2} \norm{p}^2 + \tfrac{2\lambda \sL^2}{\tau} \norm{x^n-x^m}^2,
\end{align}
%
Summing up the estimates \cref{C1}--\cref{C3}, and noticing $\tau \leq \lambda$, it follows
%
\begin{align*}
        \norm{\Fnor(z^n)}^2  & \leq  ({1-\tfrac{\tau}{2\lambda}})\|{\Fnor(z^m)}\|^2 - \tfrac{2}{\lambda}\iprod{u}{x^n-x^m} \\
        & \hspace{4ex} + [(\sL+\lambda^{-1})^2 + {2\sL^2\lambda}{\tau^{-1}}] \norm{x^n-x^m}^2 + \tfrac{3}{2\lambda\tau} \norm{p}^2.
\end{align*}

\emph{Proof of (b).} By \ref{A1}--\ref{A2}, $\nabla f$ is $\sL$-continuous and $\vp$ is convex. Thus, we have
%
\begin{equation*}
        \psi(x^n)-\psi(x^m) \leq \iprod{\nabla f(x^m)}{x^n-x^m}+\tfrac{\sL}{2}\|x^n-x^m\|^2 + \tfrac{1}{\lambda}\iprod{z^n-x^n}{x^n-x^m},
\end{equation*}
%
where we used $\lambda^{-1}(z^n-x^n) \in\partial \vp(x^n)$ in the last inequality. Moreover, based on the definition of $\Fnor$, we can reformulate %\cref{eq:lem-1-est-1} 
the above inequality as
%
\begin{align*}
\psi(x^n)-\psi(x^m) & \leq \iprod{\nabla f(x^m)+\lambda^{-1}(z^m-x^m)}{x^n-x^m}+\tfrac{\sL}{2}\|{x^n-x^m}\|^2\\
& \hspace{4ex} + \lambda^{-1}\iprod{z^n-x^n}{x^n-x^m} - \lambda^{-1}\iprod{z^m-x^m}{x^n-x^m}\\
& \hspace{-4ex} = [{\tfrac{\sL}{2}-\tfrac{1}{\lambda}}]\|{x^n-x^m}\|^2 + 	\iprod{\Fnor(z^m)}{x^n-x^m} + \tfrac{1}{\lambda}\iprod{z^n-z^m}{x^n-x^m}.
\end{align*}
%
This concludes the proof by substituting \cref{eq:u-def1} into the last expression.
\end{proof}

Using $u=(1-\lambda^{-1}\tau)\Fnor(z^m) + \lambda^{-1}p$ (cf$.$ \cref{eq:u-def3}) and $\norm{a+b}^2 \leq (1+\varepsilon) \norm{a}^2 + (1+\frac{1}{\varepsilon})\norm{b}^2$ with $a= (1-\lambda^{-1}\tau) \Fnor(z^m)$, $b = \lambda^{-1}p$, and $\varepsilon = \frac{\lambda^{-1}\tau}{1-\lambda^{-1}\tau}$, we have
%
\begin{equation}\label{C2}
        \norm{u}^2 \leq (1-\lambda^{-1}{\tau}) \|{\Fnor(z^m)}\|^2 + (\lambda\tau)^{-1} \|{p}\|^2.
\end{equation}

Utilizing Young's inequality for $2\iprod{u}{
